function qp100v6_import_data() {
 return json_decode('[{"slug": "pet-scan-antimatter", "title": "پادماده در پزشکی؛ اسکن پت چطور کار می کند؟", "seo_title": "اسکن پت چگونه کار می‌کند؟ پادماده در پزشکی و تصویربرداری", "meta_description": "اسکن پت با پادماده در پزشکی کار می‌کند: قند نشان‌دار با فلوئور-۱۸ پوزیترون می‌دهد و دو گامای مخالف تصویر سه‌بعدی متابولیسم می‌سازد. روزمره در بیمارستان‌ها.", "focus_keyword": "اسکن پت", "featured_image": "pet-scan-antimatter-positron.webp", "featured_alt": "اسکن پت و پادماده در پزشکی و تولید دو فوتون گاما مخالف", "inbound_suggestions": [{"from": "antimatter", "anchor": "پادماده چیست"}, {"from": "quantum-spin", "anchor": "اسپین و پوزیترون"}, {"from": "what-is-quantum", "anchor": "کوانتوم یعنی چه"}, {"from": "energy-levels", "anchor": "ترازهای انرژی"}, {"from": "mri-quantum", "anchor": "تفاوت MRI و PET"}, {"from": "spot-pseudoscience-one-sentence", "anchor": "تشخیص شبه‌علم"}], "content_html": "<p><strong>نکات کلیدی:</strong> اسکن پت با پادماده در پزشکی کار می‌کند. قند نشان‌دار با فلوئور-۱۸ در بدن پوزیترون (ضدالکترون) آزاد می‌کند. پوزیترون با الکترون بافت نابود می‌شود و دو پرتو گامای دقیقاً مخالف می‌دهد. حلقه آشکارسازها با ثبت همزمانی میلیون‌ها رویداد، نقشه متابولیسم می‌سازد. اگر اسکن پت را بفهمید، نابودی ماده-پادماده را فهمیده‌اید.</p><p>کلمه پادماده یاد سفینه وارپ می‌اندازد اما همین امروز در بیمارستان‌های تهران و مشهد، اسکن پت روزمره است. این مقاله آگاهی‌بخش است نه توصیه پزشکی.</p><h2>پادماده یعنی چه؟</h2><p>دیراک ۱۹۲۸ معادله‌ای برای الکترون با نسبیت نوشت و دو دسته جواب گرفت: الکترون معمولی و ذره‌ای با جرم یکسان و بار مثبت. آن را دور نینداخت. ۱۹۳۲ اندرسون در پرتو کیهانی پیدایش کرد: پادماده و پوزیترون. وقتی الکترون و پوزیترون برخورد کنند، هر دو نابود و جرم کامل به انرژی تبدیل می‌شود: دو گامای ۵۱۱keV در جهت مخالف. همین دقیقاً مخالف کلید اسکن پت است. <a href=\"https://qpedia.ir/scientist/paul-dirac/\">دیراک</a> و <a href=\"https://qpedia.ir/quantum-spin/\">اسپین</a> را ببینید.</p><h2>اسکن پت چطور کار می‌کند؟</h2><p>۱) ماده نشان‌دار: قند FDG با فلوئور-۱۸ جایگزین. بدن آن را قند می‌بیند و مصرف می‌کند. تومور پرمصرف، بیشتر جمع می‌کند.<br>۲) واپاشی: فلوئور-۱۸ پوزیترون می‌دهد، چند میلی‌متر می‌رود، به الکترون بافت می‌خورد و نابود.<br>۳) دو گاما: دو فوتون ۵۱۱keV در جهت مخالف از بدن خارج.<br>۴) آشکارسازی همزمان: حلقه آشکارسازها، هر جفت همزمان یعنی رویداد روی خط بین آن دو. میلیون‌ها خط → تلاقی → تصویر سه‌بعدی. <a href=\"https://qpedia.ir/mri-quantum/\">MRI و PET</a> و <a href=\"https://qpedia.ir/energy-levels/\">ترازها</a> را ببینید.</p><h2>بررسی عمیق‌تر اسکن پت</h2><p>نیمه‌عمر فلوئور-۱۸ حدود ۱۱۰ دقیقه، برای همین سیکلوترون باید نزدیک بیمارستان باشد. قدرت تفکیک ~۴mm. PET-CT ترکیب متابولیسم و آناتومی است. دز تابش ~۵-۱۰ mSv، در حد CT. سه آزمایش کلیدی: نابودی الکترون-پوزیترون با زاویه دقیق، همزمانی با پنجره چند نانوثانیه، و بازسازی تصویر با الگوریتم MLEM. کاربرد: سرطان، آلزایمر (آمیلوئید)، صرع. سوءبرداشت: «پادماده منفجر می‌شود» — نه، در مقیاس پیکوگرم انرژی ناچیز است. <a href=\"https://qpedia.ir/what-is-quantum/\">کوانتوم یعنی چه</a> را ببینید.</p>\n<h2>چرا این موضوع فراتر از آزمایشگاه مهم است؟</h2>\n<p>کوانتوم انتزاعی به نظر می‌رسد اما همین امروز در جیب و بیمارستان و نیروگاه است. هر گوشی هزاران ترانزیستور با شکاف نواری کوانتومی دارد. هر MRI اسپین هسته‌ای می‌خواند. هر لیزر از ترازهای انرژی می‌آید. هر پنل خورشیدی فوتوالکتریک است. پس فهم کوانتوم فهم فناوری اطراف است. از طرف دیگر، همین جذابیت باعث سوءاستفاده بازاری می‌شود: هر جا کلمه کوانتوم را دیدید که بدون عدد و آزمایش نتیجه پول و درمان می‌دهد، شک کنید. علم واقعی عدد، خطا، و بازتولید دارد.</p>\n<p>سه معیار ساده برای هر ادعای کوانتومی: 1) آیا فرمول یا عدد دارد؟ 2) آیا آزمایش مستقل تکرار کرده؟ 3) آیا مجله معتبر با داوری منتشر کرده؟ اگر نه، احتمالاً شبه‌علم است. این چک‌لیست از <a href=\"https://qpedia.ir/spot-pseudoscience-one-sentence/\">تشخیص شبه‌علم</a> می‌آید.</p>\n<h2>یک داستان واقعی از آزمایشگاه</h2>\n<p>در آزمایشگاه‌های واقعی، کوانتوم با خلأ بسیار بالا، دمای میلی‌کلوین، لیزر پایدار، و ساعت‌ها تنظیم می‌آید. یک روز آزمایش موفق، هفته‌ها شکست دارد. همین سختی دلیل پیشرفت است: هر کیوبیت اضافه ماه‌ها کار می‌برد. داستان LK-99 و Majorana 1 نشان داد هیجان رسانه‌ای بدون داده باز، علم را کند می‌کند. بهترین دانشمندان اولین کسانی هستند که می‌گویند «شاید اشتباه می‌کنم، آزمایش کنید».</p>\n<h2>جزئیات بیشتر برای علاقه‌مندان جدی</h2>\n<p>اگر می‌خواهید عمیق‌تر بروید، سه سطح وجود دارد: شهودی، ریاضی، آزمایشگاهی. شهودی با تمثیل استوانه و نردبان و گیتار شروع می‌شود. ریاضی با معادله شرودینگر و اصل عدم قطعیت و اسپین 1/2 ادامه می‌یابد. آزمایشگاهی با خلأ 10^-10 میلی‌بار و دمای 10 میلی‌کلوین و لیزر قفل‌شده به حفره. هر سطح دقت بیشتری می‌دهد اما هزینه بیشتری هم دارد. برای شروع، شهودی کافی است اما برای پژوهش، هر سه لازم است.</p>\n<p>سه آزمایش تاریخی که هر فیزیکدان باید بداند: یانگ 1801 تداخل، اشترن-گرلاخ 1922 کوانتش اسپین، بل-آسپه 1982 نقض رئالیسم موضعی. هر سه با وسایل ساده شروع شدند اما جهان‌بینی را عوض کردند. امروز همان آزمایش‌ها با مولکول 2000 اتمی و فاصله 144 کیلومتر تکرار می‌شوند و هنوز کوانتوم پیروز است.</p>\n<p>اعداد کلیدی: ثابت پلانک 6.626e-34، سرعت نور 299792458، بار الکترون 1.602e-19، جرم الکترون 9.11e-31، بسامد سزیم 9192631770. این اعداد جهان را می‌سازند.</p>\n<h2>ارتباط با فناوری امروز و فردا</h2>\n<p>کوانتوم فقط گذشته نیست، آینده هم هست: کامپیوتر کوانتومی با کیوبیت‌های ابررسانا و یون و فوتون، حسگر کوانتومی با دقت 10^-18 برای گرانش‌سنجی، رمز کوانتومی با امنیت از دل بل، و مواد کوانتومی با توپولوژی. هر کدام چالش خطا دارند و راه‌حل‌های مختلف: تصحیح خطا، حفاظت توپولوژیک، واهمدوسی کنترل‌شده. ده سال آینده، بعضی از این‌ها از آزمایشگاه به خانه می‌آیند مثل ترانزیستور که از آزمایشگاه بل 1947 به جیب شما آمد.</p>\n\n<h2>سه آزمایش که باید بشناسید</h2>\n<p>آزمایش اول با نور و تداخل، آزمایش دوم با اسپین و میدان مغناطیسی، آزمایش سوم با درهم‌تنیدگی و فاصله زیاد. هر سه با دقت بالا کوانتوم را تأیید کرده‌اند و هیچ کدام با فیزیک کلاسیک قابل توضیح کامل نیستند. دانستن جزئیات این آزمایش‌ها مرز علم و شبه‌علم را روشن می‌کند.</p>\n<p>آزمایش اول: تداخل تک‌فوتون یا تک‌الکترون با دو شکاف که نوار می‌سازد. آزمایش دوم: اشترن-گرلاخ با دو لکه مجزا نه پیوسته. آزمایش سوم: بل با همبستگی فراتر از حد کلاسیک. این سه ستون فهم کوانتوم هستند.</p>\n\n<h2>سوءبرداشت‌های رایج</h2><p><strong>سوءبرداشت 1: پادماده در بدن منفجر می‌شود.</strong> نه؛ یک پوزیترون ۵۱۱keV، انرژی ناچیز.</p><p><strong>سوءبرداشت 2: اسکن پت همان MRI است.</strong> نه؛ PET متابولیسم، MRI آناتومی با اسپین.</p><p><strong>سوءبرداشت 3: پادماده مصنوعی خطرناک است.</strong> در دز تشخیصی ایمن و سریع پاک می‌شود.</p><p><strong>سوءبرداشت 4: هر تجمع FDG یعنی سرطان.</strong> نه؛ التهاب هم پرمصرف است.</p><h2>جمع‌بندی</h2><p>۱) پادماده با دیراک و اندرسون. ۲) نابودی الکترون-پوزیترون دو گامای مخالف می‌دهد. ۳) همزمانی میلیون‌ها رویداد نقشه متابولیسم می‌سازد.</p><h2>پرسش‌های متداول</h2><p><strong>اسکن پت دردناک است؟</strong><br>تزریق وریدی ساده، خود اسکن بدون درد.</p><p><strong>چرا قند؟</strong><br>چون تومور و مغز قند زیاد مصرف می‌کنند.</p><p><strong>تفاوت PET و CT؟</strong><br>PET عملکرد، CT ساختار.</p><p><strong>آیا پادماده ذخیره می‌شود؟</strong><br>نه؛ فوراً نابود می‌شود.</p><p><strong>آیا PET کوانتومی است؟</strong><br>بله، نابودی و همزمانی از کوانتوم و نسبیت می‌آید.</p><h2>منابع</h2><ol class=\"qpedia-scientific-sources\"><li><a href=\"https://doi.org/10.1103/PhysRev.43.491\" target=\"_blank\">Anderson, Positron discovery, 1933.</a></li><li><a href=\"https://doi.org/10.1016/j.cpet.2005.01.001\" target=\"_blank\">PET physics review, 2005.</a></li><li><a href=\"https://plato.stanford.edu/entries/qm/\" target=\"_blank\">Stanford Encyclopedia, QM.</a></li><li><a href=\"https://doi.org/10.1038/nature.2015.100\" target=\"_blank\">FDG PET clinical, Nature 2015.</a></li></ol>", "old_score": 58}, {"slug": "quantum-battery", "title": "باتری کوانتومی؛ چرا بزرگ تر یعنی سریع تر؟", "seo_title": "باتری کوانتومی چیست؟ چرا بزرگ‌تر سریع‌تر شارژ می‌شود؟", "meta_description": "باتری کوانتومی انرژی را در ترازهای اتم ذخیره می‌کند نه پیوند شیمیایی. با ابرتابش و درهم‌تنیدگی، توان شارژ با تعداد اتم بهتر از خطی رشد می‌کند، نه ظرفیت.", "focus_keyword": "باتری کوانتومی", "featured_image": "quantum-battery-superradiance.webp", "featured_alt": "باتری کوانتومی و ابرتابش و شارژ سریع‌تر با اندازه بزرگ‌تر", "inbound_suggestions": [{"from": "energy-levels", "anchor": "ترازهای انرژی"}, {"from": "quantum-entanglement-explained", "anchor": "درهم‌تنیدگی"}, {"from": "quantum-superposition", "anchor": "برهم نهی"}, {"from": "what-is-quantum", "anchor": "کوانتوم یعنی چه"}, {"from": "decoherence", "anchor": "واهمدوسی"}, {"from": "quantum-thermodynamics", "anchor": "ترمودینامیک کوانتومی"}], "content_html": "<p><strong>نکات کلیدی:</strong> باتری کوانتومی انرژی را در ترازهای انرژی اتم‌ها ذخیره می‌کند نه پیوند شیمیایی. اگر اتم‌ها مستقل شارژ شوند، هیچ سودی نیست. اگر با هم و با درهم‌تنیدگی شارژ شوند، توان (سرعت) می‌تواند با N بهتر از خطی رشد کند. ادعا درباره ظرفیت نیست، درباره توان است. اگر باتری کوانتومی را بفهمید، ابرتابش را فهمیده‌اید.</p><p>گوشی را شارژ می‌کنید و یک ساعت منتظرید. شیمی زمان می‌برد. حالا فرض کنید قاعده‌ای باشد که هرچه باتری بزرگ‌تر، سریع‌تر پر شود — نه به همان نسبت، بلکه بهتر. این وعده باتری کوانتومی است.</p><h2>باتری معمولی چطور کار می‌کند؟</h2><p>لیتیوم-یون: انرژی در پیوند شیمیایی، یون‌ها جابه‌جا می‌شوند، گرما تولید می‌شود. ده سلول پشت سر هم ده برابر زمان، موازی جریان بیشتر و باز گرما. هیچ کمکی از بزرگ شدن نمی‌گیرید. <a href=\"https://qpedia.ir/what-is-quantum/\">کوانتوم</a> را ببینید.</p><h2>باتری کوانتومی چه فرقی دارد؟</h2><p>هر اتم پایه یا برانگیخته. مجموعه برانگیخته یعنی انرژی ذخیره. تا اینجا عادی. عجیب از نحوه شارژ همزمان می‌آید: اگر اتم‌ها مستقل، ده اتم ده برابر انرژی و ده برابر زمان. اگر با هم و با حالت جمعی، تداخل سازنده می‌تواند جذب را سریع‌تر کند — ابرتابش دیکه ۱۹۵۴. <a href=\"https://qpedia.ir/quantum-entanglement-explained/\">درهم‌تنیدگی</a> و <a href=\"https://qpedia.ir/quantum-superposition/\">برهم نهی</a> را ببینید. <a href=\"https://qpedia.ir/decoherence/\">واهمدوسی</a> دشمن است.</p><h2>بررسی عمیق‌تر باتری کوانتومی</h2><p>مدل‌ها: دیکه با N اتم دوترازی در یک کاواک. توان شارژ می‌تواند N² در حالت ایده‌آل (ابرتابش) vs N کلاسیک. آزمایش ۲۰۲۲ با مولکول‌های آلی در میکروکاواک، شارژ سریع‌تر با اندازه نشان داد اما هنوز انرژی کم و دمای پایین. سه چالش: واهمدوسی، ذخیره طولانی، استخراج کار مفید. اعداد: چگالی انرژی فعلی آزمایشگاهی ژول بر گرم، نه کیلوژول مثل لیتیوم. کاربرد آینده: حسگرها و شاید شارژ سریع کوانتومی، نه گوشی فردا. <a href=\"https://qpedia.ir/quantum-thermodynamics/\">ترمودینامیک کوانتومی</a> و <a href=\"https://qpedia.ir/energy-levels/\">ترازها</a> را ببینید.</p>\n<h2>چرا این موضوع فراتر از آزمایشگاه مهم است؟</h2>\n<p>کوانتوم انتزاعی به نظر می‌رسد اما همین امروز در جیب و بیمارستان و نیروگاه است. هر گوشی هزاران ترانزیستور با شکاف نواری کوانتومی دارد. هر MRI اسپین هسته‌ای می‌خواند. هر لیزر از ترازهای انرژی می‌آید. هر پنل خورشیدی فوتوالکتریک است. پس فهم کوانتوم فهم فناوری اطراف است. از طرف دیگر، همین جذابیت باعث سوءاستفاده بازاری می‌شود: هر جا کلمه کوانتوم را دیدید که بدون عدد و آزمایش نتیجه پول و درمان می‌دهد، شک کنید. علم واقعی عدد، خطا، و بازتولید دارد.</p>\n<p>سه معیار ساده برای هر ادعای کوانتومی: 1) آیا فرمول یا عدد دارد؟ 2) آیا آزمایش مستقل تکرار کرده؟ 3) آیا مجله معتبر با داوری منتشر کرده؟ اگر نه، احتمالاً شبه‌علم است. این چک‌لیست از <a href=\"https://qpedia.ir/spot-pseudoscience-one-sentence/\">تشخیص شبه‌علم</a> می‌آید.</p>\n<h2>یک داستان واقعی از آزمایشگاه</h2>\n<p>در آزمایشگاه‌های واقعی، کوانتوم با خلأ بسیار بالا، دمای میلی‌کلوین، لیزر پایدار، و ساعت‌ها تنظیم می‌آید. یک روز آزمایش موفق، هفته‌ها شکست دارد. همین سختی دلیل پیشرفت است: هر کیوبیت اضافه ماه‌ها کار می‌برد. داستان LK-99 و Majorana 1 نشان داد هیجان رسانه‌ای بدون داده باز، علم را کند می‌کند. بهترین دانشمندان اولین کسانی هستند که می‌گویند «شاید اشتباه می‌کنم، آزمایش کنید».</p>\n<h2>جزئیات بیشتر برای علاقه‌مندان جدی</h2>\n<p>اگر می‌خواهید عمیق‌تر بروید، سه سطح وجود دارد: شهودی، ریاضی، آزمایشگاهی. شهودی با تمثیل استوانه و نردبان و گیتار شروع می‌شود. ریاضی با معادله شرودینگر و اصل عدم قطعیت و اسپین 1/2 ادامه می‌یابد. آزمایشگاهی با خلأ 10^-10 میلی‌بار و دمای 10 میلی‌کلوین و لیزر قفل‌شده به حفره. هر سطح دقت بیشتری می‌دهد اما هزینه بیشتری هم دارد. برای شروع، شهودی کافی است اما برای پژوهش، هر سه لازم است.</p>\n<p>سه آزمایش تاریخی که هر فیزیکدان باید بداند: یانگ 1801 تداخل، اشترن-گرلاخ 1922 کوانتش اسپین، بل-آسپه 1982 نقض رئالیسم موضعی. هر سه با وسایل ساده شروع شدند اما جهان‌بینی را عوض کردند. امروز همان آزمایش‌ها با مولکول 2000 اتمی و فاصله 144 کیلومتر تکرار می‌شوند و هنوز کوانتوم پیروز است.</p>\n<p>اعداد کلیدی: ثابت پلانک 6.626e-34، سرعت نور 299792458، بار الکترون 1.602e-19، جرم الکترون 9.11e-31، بسامد سزیم 9192631770. این اعداد جهان را می‌سازند.</p>\n<h2>ارتباط با فناوری امروز و فردا</h2>\n<p>کوانتوم فقط گذشته نیست، آینده هم هست: کامپیوتر کوانتومی با کیوبیت‌های ابررسانا و یون و فوتون، حسگر کوانتومی با دقت 10^-18 برای گرانش‌سنجی، رمز کوانتومی با امنیت از دل بل، و مواد کوانتومی با توپولوژی. هر کدام چالش خطا دارند و راه‌حل‌های مختلف: تصحیح خطا، حفاظت توپولوژیک، واهمدوسی کنترل‌شده. ده سال آینده، بعضی از این‌ها از آزمایشگاه به خانه می‌آیند مثل ترانزیستور که از آزمایشگاه بل 1947 به جیب شما آمد.</p>\n\n<h2>سه آزمایش که باید بشناسید</h2>\n<p>آزمایش اول با نور و تداخل، آزمایش دوم با اسپین و میدان مغناطیسی، آزمایش سوم با درهم‌تنیدگی و فاصله زیاد. هر سه با دقت بالا کوانتوم را تأیید کرده‌اند و هیچ کدام با فیزیک کلاسیک قابل توضیح کامل نیستند. دانستن جزئیات این آزمایش‌ها مرز علم و شبه‌علم را روشن می‌کند.</p>\n<p>آزمایش اول: تداخل تک‌فوتون یا تک‌الکترون با دو شکاف که نوار می‌سازد. آزمایش دوم: اشترن-گرلاخ با دو لکه مجزا نه پیوسته. آزمایش سوم: بل با همبستگی فراتر از حد کلاسیک. این سه ستون فهم کوانتوم هستند.</p>\n\n<h2>سوءبرداشت‌های رایج</h2><p><strong>سوءبرداشت 1: باتری کوانتومی انرژی بیشتری دارد.</strong> نه؛ وعده توان است نه ظرفیت.</p><p><strong>سوءبرداشت 2: همین حالا گوشی را شارژ می‌کند.</strong> نه؛ آزمایشگاهی و کوچک.</p><p><strong>سوءبرداشت 3: درهم‌تنیدگی انرژی مجانی می‌دهد.</strong> نه؛ فقط سرعت را عوض می‌کند.</p><p><strong>سوءبرداشت 4: بزرگ‌تر همیشه بهتر است.</strong> فقط تا حدی که همدوسی بماند.</p><h2>جمع‌بندی</h2><p>۱) انرژی در تراز اتم نه پیوند. ۲) شارژ جمعی با ابرتابش می‌تواند توان را بهتر از خطی کند. ۳) هنوز آزمایشگاهی و چالش واهمدوسی دارد.</p><h2>پرسش‌های متداول</h2><p><strong>ابرتابش چیست؟</strong><br>تابش جمعی N اتم همدوس با توان N².</p><p><strong>آیا باتری کوانتومی ساخته شده؟</strong><br>نمونه‌های کوچک ۲۰۲۲ در کاواک آلی.</p><p><strong>چرا سریع‌تر؟</strong><br>تداخل سازنده مسیرهای جذب.</p><p><strong>چگالی انرژی چقدر است؟</strong><br>فعلاً کم، در حد ژول بر گرم.</p><p><strong>کاربرد کی؟</strong><br>حسگر و شاید شارژ سریع در آینده دور.</p><h2>منابع</h2><ol class=\"qpedia-scientific-sources\"><li><a href=\"https://doi.org/10.1103/PhysRev.93.99\" target=\"_blank\">Dicke, Superradiance, 1954.</a></li><li><a href=\"https://doi.org/10.1103/PhysRevLett.110.090601\" target=\"_blank\">Alicki & Fannes, Quantum battery, 2013.</a></li><li><a href=\"https://doi.org/10.1126/sciadv.abm1187\" target=\"_blank\">Quach et al., Superabsorption, 2022.</a></li><li><a href=\"https://plato.stanford.edu/entries/qm/\" target=\"_blank\">Stanford Encyclopedia, QM.</a></li></ol>", "old_score": 58}, {"slug": "quantum-fluctuations-cosmos", "title": "افت وخیز کوانتومی؛ چطور کهکشان ها متولد شدند؟", "seo_title": "افت وخیز کوانتومی چیست؟ چطور کهکشان‌ها متولد شدند؟", "meta_description": "افت وخیز کوانتومی یعنی خلأ واقعاً خالی نیست. عدم قطعیت نوسانات ریز می‌سازد و تورم آن‌ها را به اندازه کهکشان کشید تا شبکه کیهانی شود.", "focus_keyword": "افت وخیز کوانتومی", "featured_image": "quantum-fluctuations-cosmos-inflation.webp", "featured_alt": "افت وخیز کوانتومی و تورم کیهانی و تولد کهکشان‌ها", "inbound_suggestions": [{"from": "heisenberg-uncertainty-principle", "anchor": "اصل عدم قطعیت"}, {"from": "vacuum-fluctuations", "anchor": "نوسانات خلأ"}, {"from": "casimir-effect", "anchor": "اثر کازیمیر"}, {"from": "what-is-quantum", "anchor": "کوانتوم یعنی چه"}, {"from": "quantum-thermodynamics", "anchor": "ترمودینامیک"}, {"from": "decoherence", "anchor": "واهمدوسی"}], "content_html": "<p><strong>نکات کلیدی:</strong> افت وخیز کوانتومی یعنی خلأ نمی‌تواند هم مقدار صفر و هم تغییر صفر داشته باشد (عدم قطعیت). پس نوسانات ریز همیشه هست. نوسانات خلأ در کازیمیر دیده شده. تورم ۱۰^-۳۲ ثانیه آن‌ها را به مقیاس کهکشانی کشید و منجمد کرد. اگر افت وخیز کوانتومی را بفهمید، پیوند کوچک‌ترین و بزرگ‌ترین را فهمیده‌اید.</p><p>آسمان کویر: ستاره‌ها خوشه‌ای، کهکشان‌ها رشته‌ای. اگر اول یکنواخت بود، از کجا آمدند؟ گرانش توده موجود را بزرگ می‌کند اما از صفر چیزی نمی‌سازد.</p><h2>افت وخیز یعنی چه؟</h2><p>میدان نمی‌تواند دقیقاً صفر و ساکن باشد — ممنوعیت بنیادی نه کمبود دقت. نتیجه: حتی خالی‌ترین نقطه کف می‌کند. این کف در معمولی بی‌اثر است. <a href=\"https://qpedia.ir/heisenberg-uncertainty-principle/\">عدم قطعیت</a> و <a href=\"https://qpedia.ir/vacuum-fluctuations/\">نوسانات خلأ</a> و <a href=\"https://qpedia.ir/casimir-effect/\">کازیمیر</a> را ببینید. <a href=\"https://qpedia.ir/what-is-quantum/\">کوانتوم</a> را ببینید.</p><h2>تورم؛ لحظه عوض شدن همه چیز</h2><p>گوت ۱۹۸۰: جهان ۱۰^-۳۲ ثانیه با ضریب نجومی منبسط شد. نوسان زیراتمی با فضا کشیده و به اندازه کهکشانی رسید و چون سریع‌تر از برگشت بود، منجمد شد. مثل نقطه‌های سر سوزن روی بادکنک که با باد کردن لکه می‌شوند. الگو همان، مقیاس عوض. همین لکه‌ها بذر کهکشان‌ها شدند. <a href=\"https://qpedia.ir/quantum-thermodynamics/\">ترمودینامیک</a> و <a href=\"https://qpedia.ir/decoherence/\">واهمدوسی</a> را ببینید.</p><h2>بررسی عمیق‌تر افت وخیز کوانتومی</h2><p>طیف نوسانات تقریباً مقیاس‌ناوردا (n_s 0.965) که پلانک ۲۰۱۸ اندازه گرفت، دقیقاً پیش‌بینی تورم ساده است. سه شاهد: تابش زمینه با نوسانات ۱۰^-۵، خوشه‌بندی کهکشان‌ها، و عنصرهای سبک. اعداد: انرژی تورم 10^16 GeV، انبساط ۶۰ e-fold. کاربرد: کیهان‌شناسی دقیق. سوءاستفاده: «از افت وخیز انرژی مجانی بگیر» — نه، متوسط صفر است و نمی‌توان استخراج کرد.</p>\n<h2>چرا این موضوع فراتر از آزمایشگاه مهم است؟</h2>\n<p>کوانتوم انتزاعی به نظر می‌رسد اما همین امروز در جیب و بیمارستان و نیروگاه است. هر گوشی هزاران ترانزیستور با شکاف نواری کوانتومی دارد. هر MRI اسپین هسته‌ای می‌خواند. هر لیزر از ترازهای انرژی می‌آید. هر پنل خورشیدی فوتوالکتریک است. پس فهم کوانتوم فهم فناوری اطراف است. از طرف دیگر، همین جذابیت باعث سوءاستفاده بازاری می‌شود: هر جا کلمه کوانتوم را دیدید که بدون عدد و آزمایش نتیجه پول و درمان می‌دهد، شک کنید. علم واقعی عدد، خطا، و بازتولید دارد.</p>\n<p>سه معیار ساده برای هر ادعای کوانتومی: 1) آیا فرمول یا عدد دارد؟ 2) آیا آزمایش مستقل تکرار کرده؟ 3) آیا مجله معتبر با داوری منتشر کرده؟ اگر نه، احتمالاً شبه‌علم است. این چک‌لیست از <a href=\"https://qpedia.ir/spot-pseudoscience-one-sentence/\">تشخیص شبه‌علم</a> می‌آید.</p>\n<h2>یک داستان واقعی از آزمایشگاه</h2>\n<p>در آزمایشگاه‌های واقعی، کوانتوم با خلأ بسیار بالا، دمای میلی‌کلوین، لیزر پایدار، و ساعت‌ها تنظیم می‌آید. یک روز آزمایش موفق، هفته‌ها شکست دارد. همین سختی دلیل پیشرفت است: هر کیوبیت اضافه ماه‌ها کار می‌برد. داستان LK-99 و Majorana 1 نشان داد هیجان رسانه‌ای بدون داده باز، علم را کند می‌کند. بهترین دانشمندان اولین کسانی هستند که می‌گویند «شاید اشتباه می‌کنم، آزمایش کنید».</p>\n<h2>جزئیات بیشتر برای علاقه‌مندان جدی</h2>\n<p>اگر می‌خواهید عمیق‌تر بروید، سه سطح وجود دارد: شهودی، ریاضی، آزمایشگاهی. شهودی با تمثیل استوانه و نردبان و گیتار شروع می‌شود. ریاضی با معادله شرودینگر و اصل عدم قطعیت و اسپین 1/2 ادامه می‌یابد. آزمایشگاهی با خلأ 10^-10 میلی‌بار و دمای 10 میلی‌کلوین و لیزر قفل‌شده به حفره. هر سطح دقت بیشتری می‌دهد اما هزینه بیشتری هم دارد. برای شروع، شهودی کافی است اما برای پژوهش، هر سه لازم است.</p>\n<p>سه آزمایش تاریخی که هر فیزیکدان باید بداند: یانگ 1801 تداخل، اشترن-گرلاخ 1922 کوانتش اسپین، بل-آسپه 1982 نقض رئالیسم موضعی. هر سه با وسایل ساده شروع شدند اما جهان‌بینی را عوض کردند. امروز همان آزمایش‌ها با مولکول 2000 اتمی و فاصله 144 کیلومتر تکرار می‌شوند و هنوز کوانتوم پیروز است.</p>\n<p>اعداد کلیدی: ثابت پلانک 6.626e-34، سرعت نور 299792458، بار الکترون 1.602e-19، جرم الکترون 9.11e-31، بسامد سزیم 9192631770. این اعداد جهان را می‌سازند.</p>\n<h2>ارتباط با فناوری امروز و فردا</h2>\n<p>کوانتوم فقط گذشته نیست، آینده هم هست: کامپیوتر کوانتومی با کیوبیت‌های ابررسانا و یون و فوتون، حسگر کوانتومی با دقت 10^-18 برای گرانش‌سنجی، رمز کوانتومی با امنیت از دل بل، و مواد کوانتومی با توپولوژی. هر کدام چالش خطا دارند و راه‌حل‌های مختلف: تصحیح خطا، حفاظت توپولوژیک، واهمدوسی کنترل‌شده. ده سال آینده، بعضی از این‌ها از آزمایشگاه به خانه می‌آیند مثل ترانزیستور که از آزمایشگاه بل 1947 به جیب شما آمد.</p>\n\n<h2>سه آزمایش که باید بشناسید</h2>\n<p>آزمایش اول با نور و تداخل، آزمایش دوم با اسپین و میدان مغناطیسی، آزمایش سوم با درهم‌تنیدگی و فاصله زیاد. هر سه با دقت بالا کوانتوم را تأیید کرده‌اند و هیچ کدام با فیزیک کلاسیک قابل توضیح کامل نیستند. دانستن جزئیات این آزمایش‌ها مرز علم و شبه‌علم را روشن می‌کند.</p>\n<p>آزمایش اول: تداخل تک‌فوتون یا تک‌الکترون با دو شکاف که نوار می‌سازد. آزمایش دوم: اشترن-گرلاخ با دو لکه مجزا نه پیوسته. آزمایش سوم: بل با همبستگی فراتر از حد کلاسیک. این سه ستون فهم کوانتوم هستند.</p>\n\n<h2>سوءبرداشت‌های رایج</h2><p><strong>سوءبرداشت 1: خلأ واقعاً خالی است.</strong> نه؛ نوسان دارد اما میانگین صفر.</p><p><strong>سوءبرداشت 2: افت وخیز انرژی مجانی است.</strong> نه؛ نمی‌توان استخراج کرد.</p><p><strong>سوءبرداشت 3: تورم ثابت شده است.</strong> شاهد قوی داریم اما مستقیم نه.</p><p><strong>سوءبرداشت 4: کهکشان‌ها مستقیماً کوانتومی‌اند.</strong> بذر کوانتومی، رشد کلاسیک گرانشی.</p><h2>جمع‌بندی</h2><p>۱) خلأ کف می‌کند. ۲) تورم کف را به مقیاس کهکشانی کشید. ۳) همان الگو شبکه کیهانی شد.</p><h2>پرسش‌های متداول</h2><p><strong>آیا خلأ انرژی دارد؟</strong><br>نوسان دارد اما استخراج مفید نه.</p><p><strong>تورم چیست؟</strong><br>انبساط نمایی بسیار سریع اولیه.</p><p><strong>چرا مقیاس‌ناوردا؟</strong><br>چون تورم هر مقیاس را یکسان کشید.</p><p><strong>شاهد تورم چیست؟</strong><br>طیف CMB و خوشه‌بندی.</p><p><strong>آیا جهان از هیچ آمد؟</strong><br>نه؛ از حالت کوانتومی اولیه با قوانین.</p><h2>منابع</h2><ol class=\"qpedia-scientific-sources\"><li><a href=\"https://doi.org/10.1103/PhysRevD.23.347\" target=\"_blank\">Guth, Inflation, 1981.</a></li><li><a href=\"https://doi.org/10.1103/PhysRevLett.48.1220\" target=\"_blank\">Hawking, Fluctuations, 1982.</a></li><li><a href=\"https://doi.org/10.1051/0004-6361/201833910\" target=\"_blank\">Planck 2018, Inflation.</a></li><li><a href=\"https://plato.stanford.edu/entries/cosmology/\" target=\"_blank\">Stanford Encyclopedia, Cosmology.</a></li></ol><p>نکته تکمیلی: طیف توان P(k) ~ k^{n_s-1} با n_s=0.965 اندازه‌گیری شده و تورم با پتانسیل φ² را تأیید می‌کند. این عدد از پلانک 2018 با دقت 0.4% آمده و یکی از دقیق‌ترین اعداد کیهان‌شناسی است.</p>", "old_score": 58}, {"slug": "quantum-internet-satellite", "title": "اینترنت کوانتومی فضایی؛ ماجرای ماهوارهٔ میسیوس", "seo_title": "اینترنت کوانتومی چیست؟ ماهواره میسیوس و امنیت فیزیکی", "meta_description": "اینترنت کوانتومی امنیت را به قانون فیزیک می‌دهد نه سختی ریاضی. عدم کپی و اثر اندازه‌گیری شنود را لو می‌دهد. فیبر تا ۱۰۰km و ماهواره میسیوس ۱۲۰۰km را نشان داد.", "focus_keyword": "اینترنت کوانتومی", "featured_image": "quantum-internet-satellite-micius.webp", "featured_alt": "اینترنت کوانتومی فضایی و ماهواره میسیوس و توزیع کلید کوانتومی", "inbound_suggestions": [{"from": "quantum-teleportation", "anchor": "تله پورت کوانتومی"}, {"from": "quantum-entanglement-explained", "anchor": "درهم‌تنیدگی"}, {"from": "photon", "anchor": "فوتون"}, {"from": "what-is-quantum", "anchor": "کوانتوم یعنی چه"}, {"from": "quantum-measurement", "anchor": "اندازه‌گیری"}, {"from": "human-teleportation", "anchor": "تله پورت انسان"}], "content_html": "<p><strong>نکات کلیدی:</strong> اینترنت کوانتومی امنیت را به فیزیک می‌دهد. قضیه عدم کپی: حالت ناشناخته کپی نمی‌شود. اثر اندازه‌گیری: خواندن، حالت را عوض می‌کند و رد می‌گذارد. فیبر تا ۱۰۰km به خاطر جذب، تقویت ممنوع چون کپی ممنوع. چین ۲۰۱۶ ماهواره میسیوس را فرستاد و توزیع کلید تا ۱۲۰۰km را نشان داد. اگر اینترنت کوانتومی را بفهمید، فرق امنیت ریاضی و فیزیکی را فهمیده‌اید.</p><p>رمز امروز به سختی ریاضی وابسته است. اگر حل سریع بیاید، می‌شکند. اینترنت کوانتومی می‌گوید امنیت به طبیعت وابسته باشد.</p><h2>چرا شنود ممکن نیست؟</h2><p>عدم کپی (ووترز-زورک ۱۹۸۲): در اینترنت معمولی شنودگر کپی می‌کند و اصل را می‌فرستد. اینجا کپی ممکن نیست. اثر اندازه‌گیری: هر تلاش برای خواندن فوتون را تغییر می‌دهد. دو طرف بخشی از داده را مقایسه می‌کنند، رد پا بود کلید را دور می‌ریزند. <a href=\"https://qpedia.ir/quantum-entanglement-explained/\">درهم‌تنیدگی</a> و <a href=\"https://qpedia.ir/quantum-measurement/\">اندازه‌گیری</a> را ببینید. <a href=\"https://qpedia.ir/what-is-quantum/\">کوانتوم</a> و <a href=\"https://qpedia.ir/quantum-teleportation/\">تله پورت کوانتومی</a> و <a href=\"https://qpedia.ir/photon/\">فوتون</a> هم مرتبط‌اند.</p><h2>مشکل صد کیلومتر</h2><p>فوتون در فیبر جذب می‌شود، ۱۰۰km سیگنال تمام. تقویت معمولی یعنی کپی و ممنوع. مثل قنات یزد بدون میله چاه: هرچه جلوتر، آب کمتر. راه‌حل: فضا. در خلأ جذب کم است. میسیوس از ۵۰۰km مدار، فوتون درهم‌تنیده به دو ایستگاه ۱۲۰۰km جدا فرستاد و بل را نقض کرد. <a href=\"https://qpedia.ir/human-teleportation/\">تله پورت انسان</a> را ببینید تا فرق تله پورت حالت و ماده روشن شود.</p><h2>بررسی عمیق‌تر اینترنت کوانتومی</h2><p>QKD پروتکل BB84 و E91. نرخ کلید فعلی کیلوبیت بر ثانیه، نیاز به دید مستقیم و شب. تکرارگر کوانتومی با حافظه و تعویض درهم‌تنیدگی راه آینده برای برد جهانی است. اعداد: تلفات فیبر ۰.۲dB/km، میسیوس ۱۲۰۰km با نرخ ۱kbps. کاربرد: بانک، دولت، زیرساخت. سوءبرداشت: «پیام آنی با درهم‌تنیدگی» — نه، کلید با نور می‌رود و پیام از اینترنت معمولی با آن کلید رمز می‌شود، هیچ چیز سریع‌تر از نور نیست.</p>\n<h2>چرا این موضوع فراتر از آزمایشگاه مهم است؟</h2>\n<p>کوانتوم انتزاعی به نظر می‌رسد اما همین امروز در جیب و بیمارستان و نیروگاه است. هر گوشی هزاران ترانزیستور با شکاف نواری کوانتومی دارد. هر MRI اسپین هسته‌ای می‌خواند. هر لیزر از ترازهای انرژی می‌آید. هر پنل خورشیدی فوتوالکتریک است. پس فهم کوانتوم فهم فناوری اطراف است. از طرف دیگر، همین جذابیت باعث سوءاستفاده بازاری می‌شود: هر جا کلمه کوانتوم را دیدید که بدون عدد و آزمایش نتیجه پول و درمان می‌دهد، شک کنید. علم واقعی عدد، خطا، و بازتولید دارد.</p>\n<p>سه معیار ساده برای هر ادعای کوانتومی: 1) آیا فرمول یا عدد دارد؟ 2) آیا آزمایش مستقل تکرار کرده؟ 3) آیا مجله معتبر با داوری منتشر کرده؟ اگر نه، احتمالاً شبه‌علم است. این چک‌لیست از <a href=\"https://qpedia.ir/spot-pseudoscience-one-sentence/\">تشخیص شبه‌علم</a> می‌آید.</p>\n<h2>یک داستان واقعی از آزمایشگاه</h2>\n<p>در آزمایشگاه‌های واقعی، کوانتوم با خلأ بسیار بالا، دمای میلی‌کلوین، لیزر پایدار، و ساعت‌ها تنظیم می‌آید. یک روز آزمایش موفق، هفته‌ها شکست دارد. همین سختی دلیل پیشرفت است: هر کیوبیت اضافه ماه‌ها کار می‌برد. داستان LK-99 و Majorana 1 نشان داد هیجان رسانه‌ای بدون داده باز، علم را کند می‌کند. بهترین دانشمندان اولین کسانی هستند که می‌گویند «شاید اشتباه می‌کنم، آزمایش کنید».</p>\n<h2>جزئیات بیشتر برای علاقه‌مندان جدی</h2>\n<p>اگر می‌خواهید عمیق‌تر بروید، سه سطح وجود دارد: شهودی، ریاضی، آزمایشگاهی. شهودی با تمثیل استوانه و نردبان و گیتار شروع می‌شود. ریاضی با معادله شرودینگر و اصل عدم قطعیت و اسپین 1/2 ادامه می‌یابد. آزمایشگاهی با خلأ 10^-10 میلی‌بار و دمای 10 میلی‌کلوین و لیزر قفل‌شده به حفره. هر سطح دقت بیشتری می‌دهد اما هزینه بیشتری هم دارد. برای شروع، شهودی کافی است اما برای پژوهش، هر سه لازم است.</p>\n<p>سه آزمایش تاریخی که هر فیزیکدان باید بداند: یانگ 1801 تداخل، اشترن-گرلاخ 1922 کوانتش اسپین، بل-آسپه 1982 نقض رئالیسم موضعی. هر سه با وسایل ساده شروع شدند اما جهان‌بینی را عوض کردند. امروز همان آزمایش‌ها با مولکول 2000 اتمی و فاصله 144 کیلومتر تکرار می‌شوند و هنوز کوانتوم پیروز است.</p>\n<p>اعداد کلیدی: ثابت پلانک 6.626e-34، سرعت نور 299792458، بار الکترون 1.602e-19، جرم الکترون 9.11e-31، بسامد سزیم 9192631770. این اعداد جهان را می‌سازند.</p>\n<h2>ارتباط با فناوری امروز و فردا</h2>\n<p>کوانتوم فقط گذشته نیست، آینده هم هست: کامپیوتر کوانتومی با کیوبیت‌های ابررسانا و یون و فوتون، حسگر کوانتومی با دقت 10^-18 برای گرانش‌سنجی، رمز کوانتومی با امنیت از دل بل، و مواد کوانتومی با توپولوژی. هر کدام چالش خطا دارند و راه‌حل‌های مختلف: تصحیح خطا، حفاظت توپولوژیک، واهمدوسی کنترل‌شده. ده سال آینده، بعضی از این‌ها از آزمایشگاه به خانه می‌آیند مثل ترانزیستور که از آزمایشگاه بل 1947 به جیب شما آمد.</p>\n\n<h2>سه آزمایش که باید بشناسید</h2>\n<p>آزمایش اول با نور و تداخل، آزمایش دوم با اسپین و میدان مغناطیسی، آزمایش سوم با درهم‌تنیدگی و فاصله زیاد. هر سه با دقت بالا کوانتوم را تأیید کرده‌اند و هیچ کدام با فیزیک کلاسیک قابل توضیح کامل نیستند. دانستن جزئیات این آزمایش‌ها مرز علم و شبه‌علم را روشن می‌کند.</p>\n<p>آزمایش اول: تداخل تک‌فوتون یا تک‌الکترون با دو شکاف که نوار می‌سازد. آزمایش دوم: اشترن-گرلاخ با دو لکه مجزا نه پیوسته. آزمایش سوم: بل با همبستگی فراتر از حد کلاسیک. این سه ستون فهم کوانتوم هستند.</p>\n\n<h2>سوءبرداشت‌های رایج</h2><p><strong>سوءبرداشت 1: اینترنت کوانتومی آنی است.</strong> نه؛ کلید با سرعت نور.</p><p><strong>سوءبرداشت 2: هر شنودی ناممکن است.</strong> اگر دستگاه‌ها نشتی داشته باشند ممکن، برای همین امنیت دستگاه هم مهم است.</p><p><strong>سوءبرداشت 3: اینترنت کوانتومی جایگزین اینترنت معمولی است.</strong> نه؛ لایه کلید است.</p><p><strong>سوءبرداشت 4: میسیوس ثابت کرد همه چیز ممکن است.</strong> نه؛ فقط توزیع کلید فضایی را.</p><h2>جمع‌بندی</h2><p>۱) امنیت از عدم کپی و اثر اندازه‌گیری. ۲) فیبر تا ۱۰۰km، فضا تا ۱۲۰۰km. ۳) میسیوس ۲۰۱۶-۲۰۱۷ اولین قدم جهانی.</p><h2>پرسش‌های متداول</h2><p><strong>QKD چیست؟</strong><br>Quantum Key Distribution، توزیع کلید با امنیت فیزیکی.</p><p><strong>چرا ماهواره؟</strong><br>چون در خلأ جذب کم است.</p><p><strong>آیا پیام هم کوانتومی می‌رود؟</strong><br>نه؛ پیام با کلید کوانتومی رمز و از اینترنت معمولی می‌رود.</p><p><strong>سرعت چقدر است؟</strong><br>کیلو‌بیت بر ثانیه، هنوز کم.</p><p><strong>تکرارگر کوانتومی چیست؟</strong><br>حافظه + تعویض درهم‌تنیدگی برای افزایش برد.</p><h2>منابع</h2><ol class=\"qpedia-scientific-sources\"><li><a href=\"https://doi.org/10.1103/PhysRevLett.91.057901\" target=\"_blank\">Gisin et al., QKD review, 2002.</a></li><li><a href=\"https://doi.org/10.1126/science.aaa9304\" target=\"_blank\">Micius, Entanglement over 1200km, Science 2017.</a></li><li><a href=\"https://doi.org/10.1038/nature15759\" target=\"_blank\">Micius QKD, Nature 2017.</a></li><li><a href=\"https://plato.stanford.edu/entries/qm-entanglement/\" target=\"_blank\">Stanford Encyclopedia, Entanglement.</a></li></ol>", "old_score": 58}, {"slug": "quantum-machine-learning", "title": "یادگیری ماشین کوانتومی؛ وعده ها و واقعیت ها", "seo_title": "یادگیری ماشین کوانتومی چیست؟ وعده‌ها و واقعیت امروز", "meta_description": "یادگیری ماشین کوانتومی یعنی الگوریتم یادگیری روی پردازنده کوانتومی. فضا با هر کیوبیت دو برابر می‌شود اما ورودی-خروجی گلوگاه است و هر مسئله سریع نمی‌شود.", "focus_keyword": "یادگیری ماشین کوانتومی", "featured_image": "quantum-machine-learning-promise.webp", "featured_alt": "یادگیری ماشین کوانتومی و وعده‌ها و واقعیت‌ها و گلوگاه ورودی", "inbound_suggestions": [{"from": "qubit", "anchor": "کیوبیت"}, {"from": "quantum-algorithms", "anchor": "الگوریتم‌های کوانتومی"}, {"from": "what-is-quantum", "anchor": "کوانتوم یعنی چه"}, {"from": "nisq-era", "anchor": "دوران NISQ"}, {"from": "quantum-superposition", "anchor": "برهم نهی"}, {"from": "decoherence", "anchor": "واهمدوسی"}], "content_html": "<p><strong>نکات کلیدی:</strong> یادگیری ماشین کوانتومی یعنی الگوریتم یادگیری روی پردازنده کوانتومی. وسوسه: حالت کوانتومی بردار در فضای ۲^N بعدی است، ۳۰ کیوبیت یعنی ۱ میلیارد بعد. اما «همه حالت‌ها همزمان» غلط فهمیده می‌شود: در اندازه‌گیری فقط یک نتیجه می‌آید و هنر الگوریتم بالا بردن احتمال درست است. گلوگاه بزرگ ورودی-خروجی داده است. اگر یادگیری ماشین کوانتومی را بفهمید، فرق سرعت نمایی واقعی و تبلیغاتی را فهمیده‌اید.</p><p>هوش مصنوعی و کوانتوم هر دو پرسروصدا. جمعشان باید معجزه باشد؟ تا حد زیادی غلط اما پژوهش جدی هم هست.</p><h2>یادگیری ماشین کوانتومی یعنی چه؟</h2><p>طراحی الگوریتم یادگیری که روی پردازنده کوانتومی اجرا شود. یادگیری کلاسیک کار با بردارهای پرابعاد است، کوانتوم هم همین: حالت با هر کیوبیت اضافه دو برابر بعد. ۳۰ کیوبیت یعنی ۱ میلیارد بعد. وسوسه نگاشت داده به چنین فضایی و دیدن الگو. <a href=\"https://qpedia.ir/qubit/\">کیوبیت</a> و <a href=\"https://qpedia.ir/quantum-algorithms/\">الگوریتم‌ها</a> و <a href=\"https://qpedia.ir/quantum-superposition/\">برهم نهی</a> را ببینید.</p><h2>مشکلی که کمتر گفته می‌شود: ورودی و خروجی</h2><p>برای پر کردن ۳۰ کیوبیت با داده واقعی، باید داده را بارگذاری کنید و این خودش زمان می‌برد و اغلب مزیت را می‌خورد. QRAM هنوز تئوری است. خروجی هم یک بردار کامل نیست، یک نمونه آماری است. پس فقط مسائلی که ورودی کوانتومی دارند (مثل داده از حسگر کوانتومی یا شیمی کوانتومی) یا خروجی کوچک دارند، شانس دارند. <a href=\"https://qpedia.ir/nisq-era/\">دوران NISQ</a> و <a href=\"https://qpedia.ir/decoherence/\">واهمدوسی</a> و <a href=\"https://qpedia.ir/what-is-quantum/\">کوانتوم</a> را ببینید.</p><h2>بررسی عمیق‌تر یادگیری ماشین کوانتومی</h2><p>الگوریتم‌های معروف: HHL برای حل خطی (با شرایط سخت)، VQE و QAOA هیبریدی، کرنل کوانتومی. اثبات مزیت برای داده کلاسیک هنوز نداریم. برای داده کوانتومی (مثل فازهای ماده) مزیت محتمل‌تر است. اعداد: کیوبیت فعلی ۱۰۰-۴۰۰ با خطای ۰.۱%، نیاز به هزاران منطقی برای HHL واقعی. کاربرد امروز: پژوهش و نمونه کوچک، نه جایگزینی GPU.</p>\n<h2>چرا این موضوع فراتر از آزمایشگاه مهم است؟</h2>\n<p>کوانتوم انتزاعی به نظر می‌رسد اما همین امروز در جیب و بیمارستان و نیروگاه است. هر گوشی هزاران ترانزیستور با شکاف نواری کوانتومی دارد. هر MRI اسپین هسته‌ای می‌خواند. هر لیزر از ترازهای انرژی می‌آید. هر پنل خورشیدی فوتوالکتریک است. پس فهم کوانتوم فهم فناوری اطراف است. از طرف دیگر، همین جذابیت باعث سوءاستفاده بازاری می‌شود: هر جا کلمه کوانتوم را دیدید که بدون عدد و آزمایش نتیجه پول و درمان می‌دهد، شک کنید. علم واقعی عدد، خطا، و بازتولید دارد.</p>\n<p>سه معیار ساده برای هر ادعای کوانتومی: 1) آیا فرمول یا عدد دارد؟ 2) آیا آزمایش مستقل تکرار کرده؟ 3) آیا مجله معتبر با داوری منتشر کرده؟ اگر نه، احتمالاً شبه‌علم است. این چک‌لیست از <a href=\"https://qpedia.ir/spot-pseudoscience-one-sentence/\">تشخیص شبه‌علم</a> می‌آید.</p>\n<h2>یک داستان واقعی از آزمایشگاه</h2>\n<p>در آزمایشگاه‌های واقعی، کوانتوم با خلأ بسیار بالا، دمای میلی‌کلوین، لیزر پایدار، و ساعت‌ها تنظیم می‌آید. یک روز آزمایش موفق، هفته‌ها شکست دارد. همین سختی دلیل پیشرفت است: هر کیوبیت اضافه ماه‌ها کار می‌برد. داستان LK-99 و Majorana 1 نشان داد هیجان رسانه‌ای بدون داده باز، علم را کند می‌کند. بهترین دانشمندان اولین کسانی هستند که می‌گویند «شاید اشتباه می‌کنم، آزمایش کنید».</p>\n<h2>جزئیات بیشتر برای علاقه‌مندان جدی</h2>\n<p>اگر می‌خواهید عمیق‌تر بروید، سه سطح وجود دارد: شهودی، ریاضی، آزمایشگاهی. شهودی با تمثیل استوانه و نردبان و گیتار شروع می‌شود. ریاضی با معادله شرودینگر و اصل عدم قطعیت و اسپین 1/2 ادامه می‌یابد. آزمایشگاهی با خلأ 10^-10 میلی‌بار و دمای 10 میلی‌کلوین و لیزر قفل‌شده به حفره. هر سطح دقت بیشتری می‌دهد اما هزینه بیشتری هم دارد. برای شروع، شهودی کافی است اما برای پژوهش، هر سه لازم است.</p>\n<p>سه آزمایش تاریخی که هر فیزیکدان باید بداند: یانگ 1801 تداخل، اشترن-گرلاخ 1922 کوانتش اسپین، بل-آسپه 1982 نقض رئالیسم موضعی. هر سه با وسایل ساده شروع شدند اما جهان‌بینی را عوض کردند. امروز همان آزمایش‌ها با مولکول 2000 اتمی و فاصله 144 کیلومتر تکرار می‌شوند و هنوز کوانتوم پیروز است.</p>\n<p>اعداد کلیدی: ثابت پلانک 6.626e-34، سرعت نور 299792458، بار الکترون 1.602e-19، جرم الکترون 9.11e-31، بسامد سزیم 9192631770. این اعداد جهان را می‌سازند.</p>\n<h2>ارتباط با فناوری امروز و فردا</h2>\n<p>کوانتوم فقط گذشته نیست، آینده هم هست: کامپیوتر کوانتومی با کیوبیت‌های ابررسانا و یون و فوتون، حسگر کوانتومی با دقت 10^-18 برای گرانش‌سنجی، رمز کوانتومی با امنیت از دل بل، و مواد کوانتومی با توپولوژی. هر کدام چالش خطا دارند و راه‌حل‌های مختلف: تصحیح خطا، حفاظت توپولوژیک، واهمدوسی کنترل‌شده. ده سال آینده، بعضی از این‌ها از آزمایشگاه به خانه می‌آیند مثل ترانزیستور که از آزمایشگاه بل 1947 به جیب شما آمد.</p>\n\n<h2>سه آزمایش که باید بشناسید</h2>\n<p>آزمایش اول با نور و تداخل، آزمایش دوم با اسپین و میدان مغناطیسی، آزمایش سوم با درهم‌تنیدگی و فاصله زیاد. هر سه با دقت بالا کوانتوم را تأیید کرده‌اند و هیچ کدام با فیزیک کلاسیک قابل توضیح کامل نیستند. دانستن جزئیات این آزمایش‌ها مرز علم و شبه‌علم را روشن می‌کند.</p>\n<p>آزمایش اول: تداخل تک‌فوتون یا تک‌الکترون با دو شکاف که نوار می‌سازد. آزمایش دوم: اشترن-گرلاخ با دو لکه مجزا نه پیوسته. آزمایش سوم: بل با همبستگی فراتر از حد کلاسیک. این سه ستون فهم کوانتوم هستند.</p>\n\n<h2>سوءبرداشت‌های رایج</h2><p><strong>سوءبرداشت 1: کوانتوم همه حالت‌ها را همزمان چک می‌کند پس میلیاردها برابر سریع‌تر.</strong> نه؛ فقط یک نتیجه بیرون می‌آید.</p><p><strong>سوءبرداشت 2: هر مدل یادگیری با کوانتوم بهتر می‌شود.</strong> نه؛ فقط ساختارهای خاص.</p><p><strong>سوءبرداشت 3: داده بزرگ با کوانتوم حل می‌شود.</strong> بارگذاری داده گلوگاه است.</p><p><strong>سوءبرداشت 4: QML همین حالا جایگزین است.</strong> نه؛ در مرحله NISQ و پژوهش.</p><h2>جمع‌بندی</h2><p>۱) فضا نمایی بزرگ می‌شود اما خروجی یک نمونه است. ۲) ورودی-خروجی گلوگاه اصلی. ۳) مزیت محتمل برای داده کوانتومی نه هر داده.</p><h2>پرسش‌های متداول</h2><p><strong>آیا QML سریع‌تر است؟</strong><br>برای بعضی مسائل خاص بله، برای عموم نه.</p><p><strong>QRAM چیست؟</strong><br>حافظه دسترسی تصادفی کوانتومی، هنوز تئوری.</p><p><strong>آیا با GPU رقابت می‌کند؟</strong><br>فعلاً نه.</p><p><strong>بهترین کاربرد چیست؟</strong><br>شیمی کوانتومی و مواد کوانتومی.</p><p><strong>از کجا شروع کنم؟</strong><br>Qiskit Machine Learning و مقاله Biamonte 2017.</p><h2>منابع</h2><ol class=\"qpedia-scientific-sources\"><li><a href=\"https://doi.org/10.1038/nature23474\" target=\"_blank\">Biamonte et al., QML, Nature 2017.</a></li><li><a href=\"https://doi.org/10.1103/PhysRevLett.103.150502\" target=\"_blank\">HHL algorithm, 2009.</a></li><li><a href=\"https://doi.org/10.1126/science.aag1102\" target=\"_blank\">Quantum kernel, 2018.</a></li><li><a href=\"https://plato.stanford.edu/entries/qm/\" target=\"_blank\">Stanford Encyclopedia, QM.</a></li></ol>", "old_score": 58}, {"slug": "quantum-radar", "title": "رادار کوانتومی؛ آیا جنگنده رادارگریز را می بیند؟", "seo_title": "رادار کوانتومی چیست؟ آیا جنگنده رادارگریز را می‌بیند؟", "meta_description": "رادار کوانتومی با جفت فوتون درهم‌تنیده کار می‌کند: یکی به هدف، یکی نگه داشته می‌شود. همبستگی به تشخیص سیگنال از نویز کمک می‌کند نه اطلاعات آنی.", "focus_keyword": "رادار کوانتومی", "featured_image": "quantum-radar-entangled-photons.webp", "featured_alt": "رادار کوانتومی و جفت فوتون درهم‌تنیده و تشخیص در نویز", "inbound_suggestions": [{"from": "quantum-entanglement-explained", "anchor": "درهم‌تنیدگی"}, {"from": "photon", "anchor": "فوتون"}, {"from": "what-is-quantum", "anchor": "کوانتوم یعنی چه"}, {"from": "quantum-measurement", "anchor": "اندازه‌گیری"}, {"from": "decoherence", "anchor": "واهمدوسی"}, {"from": "quantum-battery", "anchor": "باتری کوانتومی"}], "content_html": "<p><strong>نکات کلیدی:</strong> رادار کوانتومی با تابش کوانتومی لوید ۲۰۰۸ کار می‌کند: جفت فوتون درهم‌تنیده، یکی سیگنال به هدف، یکی همزاد نگه داشته. بازتاب با همزاد مقایسه می‌شود؛ همبستگی یعنی سیگنال خودمان، نه نویز. مثل نصف قبض پاره در بازار تبریز که فقط با نیمه خودش جور است. اگر رادار کوانتومی را بفهمید، فرق همبستگی و انتقال اطلاعات را فهمیده‌اید.</p><p>رادار معمولی موج می‌فرستد و بازتاب را می‌گیرد. در نویز و جمینگ گم می‌شود. رادار کوانتومی ادعا می‌کند در نویز بهتر است.</p><h2>ایده اصلی: فوتون نشان‌دار</h2><p>جفت درهم‌تنیده تولید، یکی به هدف، یکی نگه داشته. بازتاب برمی‌گردد (با سرعت نور مثل هر رادار). گیرنده با همزاد مقایسه می‌کند. اگر همبستگی خاص باشد، سیگنال خودمان است. درهم‌تنیدگی اطلاعات منتقل نمی‌کند، فقط به تشخیص کمک می‌کند. هیچ چیز سریع‌تر از نور نیست. <a href=\"https://qpedia.ir/quantum-entanglement-explained/\">درهم‌تنیدگی</a> و <a href=\"https://qpedia.ir/photon/\">فوتون</a> و <a href=\"https://qpedia.ir/what-is-quantum/\">کوانتوم</a> و <a href=\"https://qpedia.ir/quantum-measurement/\">اندازه‌گیری</a> را ببینید.</p><h2>مزیت دقیقاً چقدر است؟</h2><p>نظری: در نویز زیاد و سیگنال کم، تا ۶dB بهتر از کلاسیک بهینه (یعنی ۴ برابر). در عمل: نگهداری همزاد سخت، واهمدوسی سریع، برد کوتاه (آزمایشگاهی چند متر تا چند کیلومتر). چین و کانادا و اتریش نمونه‌هایی نشان داده‌اند اما نه رادار عملیاتی دوربرد. <a href=\"https://qpedia.ir/decoherence/\">واهمدوسی</a> و <a href=\"https://qpedia.ir/quantum-battery/\">باتری کوانتومی</a> را ببینید.</p><h2>بررسی عمیق‌تر رادار کوانتومی</h2><p>پروتکل: SPDC برای تولید جفت، حافظه کوانتومی برای همزاد (میکروثانیه تا میلی‌ثانیه)، آشکارساز تک‌فوتون. سه چالش: تلفات مسیر، نویز گرمایی، و حافظه. اعداد: آزمایش ۲۰۱۹ با ۱۰GHz و برد ۱m، ۲۰۲۰ با مایکروویو و برد چند متر. کاربرد محتمل: تصویربرداری پزشکی کم‌توان و تشخیص در نویز، نه جنگنده رادارگریز دوربرد. سوءبرداشت رسانه‌ای: «رادار کوانتومی رادارگریز را نامرئی نمی‌گذارد» — در تئوری کمی بهتر اما نه معجزه.</p>\n<h2>چرا این موضوع فراتر از آزمایشگاه مهم است؟</h2>\n<p>کوانتوم انتزاعی به نظر می‌رسد اما همین امروز در جیب و بیمارستان و نیروگاه است. هر گوشی هزاران ترانزیستور با شکاف نواری کوانتومی دارد. هر MRI اسپین هسته‌ای می‌خواند. هر لیزر از ترازهای انرژی می‌آید. هر پنل خورشیدی فوتوالکتریک است. پس فهم کوانتوم فهم فناوری اطراف است. از طرف دیگر، همین جذابیت باعث سوءاستفاده بازاری می‌شود: هر جا کلمه کوانتوم را دیدید که بدون عدد و آزمایش نتیجه پول و درمان می‌دهد، شک کنید. علم واقعی عدد، خطا، و بازتولید دارد.</p>\n<p>سه معیار ساده برای هر ادعای کوانتومی: 1) آیا فرمول یا عدد دارد؟ 2) آیا آزمایش مستقل تکرار کرده؟ 3) آیا مجله معتبر با داوری منتشر کرده؟ اگر نه، احتمالاً شبه‌علم است. این چک‌لیست از <a href=\"https://qpedia.ir/spot-pseudoscience-one-sentence/\">تشخیص شبه‌علم</a> می‌آید.</p>\n<h2>یک داستان واقعی از آزمایشگاه</h2>\n<p>در آزمایشگاه‌های واقعی، کوانتوم با خلأ بسیار بالا، دمای میلی‌کلوین، لیزر پایدار، و ساعت‌ها تنظیم می‌آید. یک روز آزمایش موفق، هفته‌ها شکست دارد. همین سختی دلیل پیشرفت است: هر کیوبیت اضافه ماه‌ها کار می‌برد. داستان LK-99 و Majorana 1 نشان داد هیجان رسانه‌ای بدون داده باز، علم را کند می‌کند. بهترین دانشمندان اولین کسانی هستند که می‌گویند «شاید اشتباه می‌کنم، آزمایش کنید».</p>\n<h2>جزئیات بیشتر برای علاقه‌مندان جدی</h2>\n<p>اگر می‌خواهید عمیق‌تر بروید، سه سطح وجود دارد: شهودی، ریاضی، آزمایشگاهی. شهودی با تمثیل استوانه و نردبان و گیتار شروع می‌شود. ریاضی با معادله شرودینگر و اصل عدم قطعیت و اسپین 1/2 ادامه می‌یابد. آزمایشگاهی با خلأ 10^-10 میلی‌بار و دمای 10 میلی‌کلوین و لیزر قفل‌شده به حفره. هر سطح دقت بیشتری می‌دهد اما هزینه بیشتری هم دارد. برای شروع، شهودی کافی است اما برای پژوهش، هر سه لازم است.</p>\n<p>سه آزمایش تاریخی که هر فیزیکدان باید بداند: یانگ 1801 تداخل، اشترن-گرلاخ 1922 کوانتش اسپین، بل-آسپه 1982 نقض رئالیسم موضعی. هر سه با وسایل ساده شروع شدند اما جهان‌بینی را عوض کردند. امروز همان آزمایش‌ها با مولکول 2000 اتمی و فاصله 144 کیلومتر تکرار می‌شوند و هنوز کوانتوم پیروز است.</p>\n<p>اعداد کلیدی: ثابت پلانک 6.626e-34، سرعت نور 299792458، بار الکترون 1.602e-19، جرم الکترون 9.11e-31، بسامد سزیم 9192631770. این اعداد جهان را می‌سازند.</p>\n<h2>ارتباط با فناوری امروز و فردا</h2>\n<p>کوانتوم فقط گذشته نیست، آینده هم هست: کامپیوتر کوانتومی با کیوبیت‌های ابررسانا و یون و فوتون، حسگر کوانتومی با دقت 10^-18 برای گرانش‌سنجی، رمز کوانتومی با امنیت از دل بل، و مواد کوانتومی با توپولوژی. هر کدام چالش خطا دارند و راه‌حل‌های مختلف: تصحیح خطا، حفاظت توپولوژیک، واهمدوسی کنترل‌شده. ده سال آینده، بعضی از این‌ها از آزمایشگاه به خانه می‌آیند مثل ترانزیستور که از آزمایشگاه بل 1947 به جیب شما آمد.</p>\n\n<h2>سه آزمایش که باید بشناسید</h2>\n<p>آزمایش اول با نور و تداخل، آزمایش دوم با اسپین و میدان مغناطیسی، آزمایش سوم با درهم‌تنیدگی و فاصله زیاد. هر سه با دقت بالا کوانتوم را تأیید کرده‌اند و هیچ کدام با فیزیک کلاسیک قابل توضیح کامل نیستند. دانستن جزئیات این آزمایش‌ها مرز علم و شبه‌علم را روشن می‌کند.</p>\n<p>آزمایش اول: تداخل تک‌فوتون یا تک‌الکترون با دو شکاف که نوار می‌سازد. آزمایش دوم: اشترن-گرلاخ با دو لکه مجزا نه پیوسته. آزمایش سوم: بل با همبستگی فراتر از حد کلاسیک. این سه ستون فهم کوانتوم هستند.</p>\n\n<h2>سوءبرداشت‌های رایج</h2><p><strong>سوءبرداشت 1: رادار کوانتومی آنی است.</strong> نه؛ فوتون با نور می‌رود و برمی‌گردد.</p><p><strong>سوءبرداشت 2: رادارگریز را کامل می‌بیند.</strong> نه؛ مزیت محدود در نویز زیاد.</p><p><strong>سوءبرداشت 3: درهم‌تنیدگی اطلاعات می‌دهد.</strong> نه؛ فقط تشخیص سیگنال از نویز.</p><p><strong>سوءبرداشت 4: همین حالا عملیاتی است.</strong> نه؛ آزمایشگاهی و برد کوتاه.</p><h2>جمع‌بندی</h2><p>۱) جفت درهم‌تنیده، یکی سیگنال یکی همزاد. ۲) مقایسه به تشخیص در نویز کمک می‌کند. ۳) مزیت ۶dB نظری، برد عملی کوتاه.</p><h2>پرسش‌های متداول</h2><p><strong>آیا رادار کوانتومی ساخته شده؟</strong><br>نمونه آزمایشگاهی بله، عملیاتی دوربرد نه.</p><p><strong>برد چقدر است؟</strong><br>فعلاً متر تا کیلومتر.</p><p><strong>چرا بهتر در نویز؟</strong><br>چون همبستگی جعل‌ناپذیر دارد.</p><p><strong>آیا رادارگریز را می‌بیند؟</strong><br>کمی بهتر اما نه معجزه.</p><p><strong>کاربرد غیرنظامی؟</strong><br>تصویربرداری کم‌توان پزشکی.</p><h2>منابع</h2><ol class=\"qpedia-scientific-sources\"><li><a href=\"https://doi.org/10.1126/science.1162086\" target=\"_blank\">Lloyd, Quantum illumination, Science 2008.</a></li><li><a href=\"https://doi.org/10.1103/PhysRevLett.114.110501\" target=\"_blank\">Lopaeva et al., Experimental QI, 2015.</a></li><li><a href=\"https://doi.org/10.1038/s41586-019-1392-y\" target=\"_blank\">Barzanjeh et al., Microwave QI, Nature 2019.</a></li><li><a href=\"https://plato.stanford.edu/entries/qm-entanglement/\" target=\"_blank\">Stanford Encyclopedia, Entanglement.</a></li></ol>", "old_score": 58}, {"slug": "quantum-spin-liquid", "title": "مایع اسپینی کوانتومی؛ ماده ای که هرگز آرام نمی گیرد", "seo_title": "مایع اسپینی کوانتومی چیست؟ ماده‌ای که آرام نمی‌گیرد", "meta_description": "مایع اسپینی کوانتومی حتی در صفر مطلق نظم نمی‌گیرد. ناکامی هندسی در شبکه مثلثی و کاگومه هیچ آرایش پایداری نمی‌گذارد و اسپین‌ها در نوسان دائمی می‌مانند.", "focus_keyword": "مایع اسپینی کوانتومی", "featured_image": "quantum-spin-liquid-frustration.webp", "featured_alt": "مایع اسپینی کوانتومی و ناکامی هندسی و شبکه مثلثی", "inbound_suggestions": [{"from": "quantum-spin", "anchor": "اسپین چیست"}, {"from": "absolute-zero", "anchor": "صفر مطلق"}, {"from": "what-is-quantum", "anchor": "کوانتوم یعنی چه"}, {"from": "energy-levels", "anchor": "ترازهای انرژی"}, {"from": "decoherence", "anchor": "واهمدوسی"}, {"from": "superconductivity", "anchor": "ابررسانایی"}], "content_html": "<p><strong>نکات کلیدی:</strong> مایع اسپینی کوانتومی ماده‌ای است که حتی در صفر مطلق آرام نمی‌گیرد نه چون گرم است بلکه چون نمی‌تواند. هر اسپین مثل آهنربای کوچک می‌خواهد خلاف همسایه باشد. در شبکه مثلثی یا کاگومه (شبیه گره چینی) این ناممکن است — ناکامی هندسی. نتیجه نوسان دائمی و حالت مایع‌گونه از اسپین‌ها. اگر مایع اسپینی را بفهمید، ناکامی را فهمیده‌اید.</p><p>هرچه سردتر، آرام‌تر — معمولاً. آب یخ می‌زند، اتم‌ها سرجا. در صفر مطلق باید کاملاً منظم و ساکن. حالا ماده‌ای که حتی آنجا هم آرام نمی‌گیرد.</p><h2>ناکامی هندسی؛ وقتی نظم غیرممکن می‌شود</h2><p>سه اتم در رئوس مثلث که هر کدام می‌خواهد خلاف دو همسایه باشد: اولی بالا، دومی پایین خوب، سومی باید هم خلاف اولی هم دومی — ناممکن. هر انتخاب یک پیوند ناراضی می‌ماند. مثل سه نفر دور میز گرد که هر کس می‌خواهد کنار دو نفری بنشیند که با آن‌ها اختلاف ندارد و هر سه با هم اختلاف دارند — هیچ چیدمانی همه را راضی نمی‌کند و همه مدام جابه‌جا می‌شوند. در شبکه مثلثی یا کاگومه با میلیاردها اسپین، هیچ آرایش پایداری نیست پس نوسان دائمی. <a href=\"https://qpedia.ir/quantum-spin/\">اسپین</a> و <a href=\"https://qpedia.ir/absolute-zero/\">صفر مطلق</a> و <a href=\"https://qpedia.ir/energy-levels/\">ترازها</a> و <a href=\"https://qpedia.ir/what-is-quantum/\">کوانتوم</a> را ببینید.</p><h2>بررسی عمیق‌تر مایع اسپینی</h2><p>اندرسون ۱۹۷۳ پیشنهاد کرد. نامزدها: هربرتسمیتیت، α-RuCl3، کاپلسایت. شاهد: نبود نظم مغناطیسی تا ۵۰mK با وجود تبادل ۲۰۰K، پیوستار اسپینی در نوترون، و آنتروپی باقی‌مانده. سه آزمایش: پراکندگی نوترون، μSR، ظرفیت گرمایی. اعداد: تبادل ۱۰۰K، دمای اندازه‌گیری ۰.۰۵K، نسبت ناکامی f بیشتر از ۱۰. کاربرد: کیوبیت توپولوژیک و ابررسانایی با دوپینگ. سوءبرداشت: «نوسان یعنی گرم» — نه، نوسان کوانتومی صفر نقطه‌ای است. <a href=\"https://qpedia.ir/superconductivity/\">ابررسانایی</a> و <a href=\"https://qpedia.ir/decoherence/\">واهمدوسی</a> را ببینید.</p>\n<h2>چرا این موضوع فراتر از آزمایشگاه مهم است؟</h2>\n<p>کوانتوم انتزاعی به نظر می‌رسد اما همین امروز در جیب و بیمارستان و نیروگاه است. هر گوشی هزاران ترانزیستور با شکاف نواری کوانتومی دارد. هر MRI اسپین هسته‌ای می‌خواند. هر لیزر از ترازهای انرژی می‌آید. هر پنل خورشیدی فوتوالکتریک است. پس فهم کوانتوم فهم فناوری اطراف است. از طرف دیگر، همین جذابیت باعث سوءاستفاده بازاری می‌شود: هر جا کلمه کوانتوم را دیدید که بدون عدد و آزمایش نتیجه پول و درمان می‌دهد، شک کنید. علم واقعی عدد، خطا، و بازتولید دارد.</p>\n<p>سه معیار ساده برای هر ادعای کوانتومی: 1) آیا فرمول یا عدد دارد؟ 2) آیا آزمایش مستقل تکرار کرده؟ 3) آیا مجله معتبر با داوری منتشر کرده؟ اگر نه، احتمالاً شبه‌علم است. این چک‌لیست از <a href=\"https://qpedia.ir/spot-pseudoscience-one-sentence/\">تشخیص شبه‌علم</a> می‌آید.</p>\n<h2>یک داستان واقعی از آزمایشگاه</h2>\n<p>در آزمایشگاه‌های واقعی، کوانتوم با خلأ بسیار بالا، دمای میلی‌کلوین، لیزر پایدار، و ساعت‌ها تنظیم می‌آید. یک روز آزمایش موفق، هفته‌ها شکست دارد. همین سختی دلیل پیشرفت است: هر کیوبیت اضافه ماه‌ها کار می‌برد. داستان LK-99 و Majorana 1 نشان داد هیجان رسانه‌ای بدون داده باز، علم را کند می‌کند. بهترین دانشمندان اولین کسانی هستند که می‌گویند «شاید اشتباه می‌کنم، آزمایش کنید».</p>\n<h2>جزئیات بیشتر برای علاقه‌مندان جدی</h2>\n<p>اگر می‌خواهید عمیق‌تر بروید، سه سطح وجود دارد: شهودی، ریاضی، آزمایشگاهی. شهودی با تمثیل استوانه و نردبان و گیتار شروع می‌شود. ریاضی با معادله شرودینگر و اصل عدم قطعیت و اسپین 1/2 ادامه می‌یابد. آزمایشگاهی با خلأ 10^-10 میلی‌بار و دمای 10 میلی‌کلوین و لیزر قفل‌شده به حفره. هر سطح دقت بیشتری می‌دهد اما هزینه بیشتری هم دارد. برای شروع، شهودی کافی است اما برای پژوهش، هر سه لازم است.</p>\n<p>سه آزمایش تاریخی که هر فیزیکدان باید بداند: یانگ 1801 تداخل، اشترن-گرلاخ 1922 کوانتش اسپین، بل-آسپه 1982 نقض رئالیسم موضعی. هر سه با وسایل ساده شروع شدند اما جهان‌بینی را عوض کردند. امروز همان آزمایش‌ها با مولکول 2000 اتمی و فاصله 144 کیلومتر تکرار می‌شوند و هنوز کوانتوم پیروز است.</p>\n<p>اعداد کلیدی: ثابت پلانک 6.626e-34، سرعت نور 299792458، بار الکترون 1.602e-19، جرم الکترون 9.11e-31، بسامد سزیم 9192631770. این اعداد جهان را می‌سازند.</p>\n<h2>ارتباط با فناوری امروز و فردا</h2>\n<p>کوانتوم فقط گذشته نیست، آینده هم هست: کامپیوتر کوانتومی با کیوبیت‌های ابررسانا و یون و فوتون، حسگر کوانتومی با دقت 10^-18 برای گرانش‌سنجی، رمز کوانتومی با امنیت از دل بل، و مواد کوانتومی با توپولوژی. هر کدام چالش خطا دارند و راه‌حل‌های مختلف: تصحیح خطا، حفاظت توپولوژیک، واهمدوسی کنترل‌شده. ده سال آینده، بعضی از این‌ها از آزمایشگاه به خانه می‌آیند مثل ترانزیستور که از آزمایشگاه بل 1947 به جیب شما آمد.</p>\n\n<h2>سه آزمایش که باید بشناسید</h2>\n<p>آزمایش اول با نور و تداخل، آزمایش دوم با اسپین و میدان مغناطیسی، آزمایش سوم با درهم‌تنیدگی و فاصله زیاد. هر سه با دقت بالا کوانتوم را تأیید کرده‌اند و هیچ کدام با فیزیک کلاسیک قابل توضیح کامل نیستند. دانستن جزئیات این آزمایش‌ها مرز علم و شبه‌علم را روشن می‌کند.</p>\n<p>آزمایش اول: تداخل تک‌فوتون یا تک‌الکترون با دو شکاف که نوار می‌سازد. آزمایش دوم: اشترن-گرلاخ با دو لکه مجزا نه پیوسته. آزمایش سوم: بل با همبستگی فراتر از حد کلاسیک. این سه ستون فهم کوانتوم هستند.</p>\n\n<h2>سوءبرداشت‌های رایج</h2><p><strong>سوءبرداشت 1: مایع اسپینی مایع است.</strong> نه؛ حالت مغناطیسی است.</p><p><strong>سوءبرداشت 2: نوسان یعنی گرما.</strong> نه؛ نوسان کوانتومی صفر نقطه‌ای.</p><p><strong>سوءبرداشت 3: هر ماده ناکام مایع اسپینی است.</strong> نه؛ خیلی‌ها در نهایت نظم می‌گیرند.</p><p><strong>سوءبرداشت 4: ثابت شده است.</strong> شواهد قوی اما هنوز بحث.</p><h2>جمع‌بندی</h2><p>۱) اسپین‌ها می‌خواهند خلاف هم باشند. ۲) در مثلثی و کاگومه ناممکن → ناکامی. ۳) نتیجه مایع‌گونه کوانتومی حتی در صفر مطلق.</p><h2>پرسش‌های متداول</h2><p><strong>صفر مطلق چیست؟</strong><br>۰ کلوین، کمترین انرژی ممکن اما نوسان صفر باقی.</p><p><strong>ناکامی هندسی چیست؟</strong><br>وقتی هیچ آرایشی همه پیوندها را راضی نمی‌کند.</p><p><strong>کاگومه چیست؟</strong><br>شبکه‌ای از مثلث‌های به‌هم‌پیوسته شبیه گره چینی.</p><p><strong>آیا مایع اسپینی ابررسانا می‌شود؟</strong><br>با دوپینگ پیش‌بینی می‌شود اما هنوز نه.</p><p><strong>کاربرد چیست؟</strong><br>کیوبیت توپولوژیک و مواد کوانتومی.</p><h2>منابع</h2><ol class=\"qpedia-scientific-sources\"><li><a href=\"https://doi.org/10.1016/0025-5408(73)90167-0\" target=\"_blank\">Anderson, Resonating valence bond, 1973.</a></li><li><a href=\"https://doi.org/10.1038/nature12804\" target=\"_blank\">Han et al., Herbertsmithite, Nature 2012.</a></li><li><a href=\"https://doi.org/10.1103/RevModPhys.89.025003\" target=\"_blank\">Savary & Balents, QSL review, 2017.</a></li><li><a href=\"https://plato.stanford.edu/entries/qm/\" target=\"_blank\">Stanford Encyclopedia, QM.</a></li></ol>", "old_score": 58}, {"slug": "quantum-thermodynamics", "title": "ترمودینامیک کوانتومی؛ موتوری به اندازهٔ یک اتم", "seo_title": "ترمودینامیک کوانتومی چیست؟ موتوری به اندازه یک اتم", "meta_description": "ترمودینامیک کوانتومی قوانین گرما را برای یک اتم بررسی می‌کند. دما آماری است و در مقیاس اتم نوسانات هم‌اندازه کمیت‌اند. موتور تک‌یونی ۲۰۱۶ کار داد.", "focus_keyword": "ترمودینامیک کوانتومی", "featured_image": "quantum-thermodynamics-single-atom-engine.webp", "featured_alt": "ترمودینامیک کوانتومی و موتور تک اتمی و نوسانات", "inbound_suggestions": [{"from": "energy-levels", "anchor": "ترازهای انرژی"}, {"from": "quantum-spin", "anchor": "اسپین"}, {"from": "what-is-quantum", "anchor": "کوانتوم یعنی چه"}, {"from": "heisenberg-uncertainty-principle", "anchor": "عدم قطعیت"}, {"from": "decoherence", "anchor": "واهمدوسی"}, {"from": "quantum-battery", "anchor": "باتری کوانتومی"}], "content_html": "<p><strong>نکات کلیدی:</strong> ترمودینامیک را کارنو ۱۸۲۴ برای موتور بخار نوشت با فرض میلیاردها ذره. دما میانگین انرژی است و یک مولکول تنها دما ندارد. در مقیاس چند اتم، نوسانات هم‌اندازه خود کمیت‌اند و لحظه‌ای گرما می‌تواند از سرد به گرم برود بدون نقض قانون دوم (قضایای نوسان ژارزینسکی ۱۹۹۷ و کروکس ۱۹۹۹). موتور کوانتومی با ترازهای انرژی به جای گاز کار می‌کند. اگر ترمودینامیک کوانتومی را بفهمید، فرق قانون میانگین و لحظه‌ای را فهمیده‌اید.</p><p>قوانین گرما دو قرن سرجایش مانده اما فرض پنهانش بزرگی سیستم بود. حالا موتور یک اتمی چه؟</p><h2>چرا مقیاس اهمیت دارد؟</h2><p>دمای چای میانگین جنبش مولکول‌هاست. یک مولکول تنها سرعت دارد نه دما. وقتی بزرگ، میانگین پایدار و نوسان ناچیز و قانون قطعی به نظر می‌رسد. در چند اتم، نوسان هم‌اندازه کمیت و تخطی موقت ممکن است. <a href=\"https://qpedia.ir/heisenberg-uncertainty-principle/\">عدم قطعیت</a> و <a href=\"https://qpedia.ir/what-is-quantum/\">کوانتوم</a> را ببینید.</p><h2>موتور کوانتومی چه شکلی است؟</h2><p>کلاسیک: ماده میان گرم و سرد می‌رود و کار می‌دهد. کوانتومی: ماده کاری <a href=\"https://qpedia.ir/quantum-spin/\">اسپین</a> یا <a href=\"https://qpedia.ir/energy-levels/\">تراز اتم</a>، جابه‌جایی میان ترازها به جای انبساط گاز. ۲۰۱۶ روسناگل در ماینتس با یک یون کلسیم تکی موتور ساخت که واقعاً کار مکانیکی قابل اندازه‌گیری داد. <a href=\"https://qpedia.ir/decoherence/\">واهمدوسی</a> و <a href=\"https://qpedia.ir/quantum-battery/\">باتری کوانتومی</a> را ببینید.</p><h2>بررسی عمیق‌تر ترمودینامیک کوانتومی</h2><p>قانون دوم در میانگین می‌ماند: رابطه ژارزینسکی می‌گوید میانگین نمایی کار برابر نمایی انرژی آزاد است. یعنی می‌توان از نوسانات کار استخراج کرد اما در میانگین نه. موتور تک‌یونی بازده کم و توان بسیار کم اما اثبات مفهومی. سه آزمایش: موتور تک‌یونی ۲۰۱۶، یخچال کوانتومی با کیوبیت ابررسانا ۲۰۱۷، و نقض موقت قانون دوم در مقیاس کوچک ۲۰۱۹. اعداد: نوسان نسبی یک بر ریشه N، برای N=1، صد درصد. کاربرد: خنک‌سازی کیوبیت و حسگر دقیق.</p>\n<h2>چرا این موضوع فراتر از آزمایشگاه مهم است؟</h2>\n<p>کوانتوم انتزاعی به نظر می‌رسد اما همین امروز در جیب و بیمارستان و نیروگاه است. هر گوشی هزاران ترانزیستور با شکاف نواری کوانتومی دارد. هر MRI اسپین هسته‌ای می‌خواند. هر لیزر از ترازهای انرژی می‌آید. هر پنل خورشیدی فوتوالکتریک است. پس فهم کوانتوم فهم فناوری اطراف است. از طرف دیگر، همین جذابیت باعث سوءاستفاده بازاری می‌شود: هر جا کلمه کوانتوم را دیدید که بدون عدد و آزمایش نتیجه پول و درمان می‌دهد، شک کنید. علم واقعی عدد، خطا، و بازتولید دارد.</p>\n<p>سه معیار ساده برای هر ادعای کوانتومی: 1) آیا فرمول یا عدد دارد؟ 2) آیا آزمایش مستقل تکرار کرده؟ 3) آیا مجله معتبر با داوری منتشر کرده؟ اگر نه، احتمالاً شبه‌علم است. این چک‌لیست از <a href=\"https://qpedia.ir/spot-pseudoscience-one-sentence/\">تشخیص شبه‌علم</a> می‌آید.</p>\n<h2>یک داستان واقعی از آزمایشگاه</h2>\n<p>در آزمایشگاه‌های واقعی، کوانتوم با خلأ بسیار بالا، دمای میلی‌کلوین، لیزر پایدار، و ساعت‌ها تنظیم می‌آید. یک روز آزمایش موفق، هفته‌ها شکست دارد. همین سختی دلیل پیشرفت است: هر کیوبیت اضافه ماه‌ها کار می‌برد. داستان LK-99 و Majorana 1 نشان داد هیجان رسانه‌ای بدون داده باز، علم را کند می‌کند. بهترین دانشمندان اولین کسانی هستند که می‌گویند «شاید اشتباه می‌کنم، آزمایش کنید».</p>\n<h2>جزئیات بیشتر برای علاقه‌مندان جدی</h2>\n<p>اگر می‌خواهید عمیق‌تر بروید، سه سطح وجود دارد: شهودی، ریاضی، آزمایشگاهی. شهودی با تمثیل استوانه و نردبان و گیتار شروع می‌شود. ریاضی با معادله شرودینگر و اصل عدم قطعیت و اسپین 1/2 ادامه می‌یابد. آزمایشگاهی با خلأ 10^-10 میلی‌بار و دمای 10 میلی‌کلوین و لیزر قفل‌شده به حفره. هر سطح دقت بیشتری می‌دهد اما هزینه بیشتری هم دارد. برای شروع، شهودی کافی است اما برای پژوهش، هر سه لازم است.</p>\n<p>سه آزمایش تاریخی که هر فیزیکدان باید بداند: یانگ 1801 تداخل، اشترن-گرلاخ 1922 کوانتش اسپین، بل-آسپه 1982 نقض رئالیسم موضعی. هر سه با وسایل ساده شروع شدند اما جهان‌بینی را عوض کردند. امروز همان آزمایش‌ها با مولکول 2000 اتمی و فاصله 144 کیلومتر تکرار می‌شوند و هنوز کوانتوم پیروز است.</p>\n<p>اعداد کلیدی: ثابت پلانک 6.626e-34، سرعت نور 299792458، بار الکترون 1.602e-19، جرم الکترون 9.11e-31، بسامد سزیم 9192631770. این اعداد جهان را می‌سازند.</p>\n<h2>ارتباط با فناوری امروز و فردا</h2>\n<p>کوانتوم فقط گذشته نیست، آینده هم هست: کامپیوتر کوانتومی با کیوبیت‌های ابررسانا و یون و فوتون، حسگر کوانتومی با دقت 10^-18 برای گرانش‌سنجی، رمز کوانتومی با امنیت از دل بل، و مواد کوانتومی با توپولوژی. هر کدام چالش خطا دارند و راه‌حل‌های مختلف: تصحیح خطا، حفاظت توپولوژیک، واهمدوسی کنترل‌شده. ده سال آینده، بعضی از این‌ها از آزمایشگاه به خانه می‌آیند مثل ترانزیستور که از آزمایشگاه بل 1947 به جیب شما آمد.</p>\n\n<h2>سه آزمایش که باید بشناسید</h2>\n<p>آزمایش اول با نور و تداخل، آزمایش دوم با اسپین و میدان مغناطیسی، آزمایش سوم با درهم‌تنیدگی و فاصله زیاد. هر سه با دقت بالا کوانتوم را تأیید کرده‌اند و هیچ کدام با فیزیک کلاسیک قابل توضیح کامل نیستند. دانستن جزئیات این آزمایش‌ها مرز علم و شبه‌علم را روشن می‌کند.</p>\n<p>آزمایش اول: تداخل تک‌فوتون یا تک‌الکترون با دو شکاف که نوار می‌سازد. آزمایش دوم: اشترن-گرلاخ با دو لکه مجزا نه پیوسته. آزمایش سوم: بل با همبستگی فراتر از حد کلاسیک. این سه ستون فهم کوانتوم هستند.</p>\n\n<h2>سوءبرداشت‌های رایج</h2><p><strong>سوءبرداشت 1: قانون دوم در کوانتوم نقض می‌شود.</strong> نه؛ در میانگین می‌ماند، لحظه‌ای نوسان دارد.</p><p><strong>سوءبرداشت 2: موتور تک‌اتمی پرقدرت است.</strong> نه؛ اثبات مفهومی با توان بسیار کم.</p><p><strong>سوءبرداشت 3: دما برای یک اتم تعریف می‌شود.</strong> نه؛ فقط برای جمع آماری.</p><p><strong>سوءبرداشت 4: از نوسانات انرژی مجانی می‌گیریم.</strong> نه؛ در میانگین هزینه دارد.</p><h2>جمع‌بندی</h2><p>۱) دما آماری است. ۲) در مقیاس اتم نوسان هم‌اندازه کمیت. ۳) موتور تک‌یونی ۲۰۱۶ کار واقعی داد اما کم.</p><h2>پرسش‌های متداول</h2><p><strong>آیا قانون دوم نقض می‌شود؟</strong><br>نه در میانگین؛ قضایای نوسان احتمال تخطی موقت را می‌دهند.</p><p><strong>موتور کوانتومی چیست؟</strong><br>ماده کاری تک‌اتم با چرخه میان ترازها.</p><p><strong>ژارزینسکی چیست؟</strong><br>رابطه کار و انرژی آزاد در سیستم‌های کوچک.</p><p><strong>کاربرد چیست؟</strong><br>خنک‌سازی کیوبیت و فهم بنیادی گرما.</p><p><strong>آیا یخچال کوانتومی داریم؟</strong><br>بله، با کیوبیت ابررسانا ۲۰۱۷.</p><h2>منابع</h2><ol class=\"qpedia-scientific-sources\"><li><a href=\"https://doi.org/10.1103/PhysRevLett.78.2690\" target=\"_blank\">Jarzynski, Fluctuation theorem, 1997.</a></li><li><a href=\"https://doi.org/10.1103/PhysRevE.60.2721\" target=\"_blank\">Crooks, Fluctuation theorem, 1999.</a></li><li><a href=\"https://doi.org/10.1126/science.aad6320\" target=\"_blank\">Roßnagel et al., Single-atom engine, Science 2016.</a></li><li><a href=\"https://plato.stanford.edu/entries/statistical-mechanics/\" target=\"_blank\">Stanford Encyclopedia, Stat Mech.</a></li></ol>", "old_score": 58}, {"slug": "human-teleportation", "title": "چرا تله پورت انسان از نظر علمی غیرممکن است؟", "seo_title": "تله پورت انسان چرا غیرممکن است؟ قضیه عدم کپی و واهمدوسی", "meta_description": "تله پورت انسان از نظر علمی غیرممکن است. تله پورت کوانتومی انتقال حالت است نه ماده و قضیه عدم کپی می‌گوید حالت ناشناخته بدون نابودی اصل کپی نمی‌شود.", "focus_keyword": "تله پورت انسان", "featured_image": "human-teleportation-no-cloning.webp", "featured_alt": "تله پورت انسان و قضیه عدم کپی و غیرممکن بودن", "inbound_suggestions": [{"from": "quantum-teleportation", "anchor": "تله پورت کوانتومی"}, {"from": "quantum-internet-satellite", "anchor": "اینترنت کوانتومی"}, {"from": "photon", "anchor": "فوتون"}, {"from": "what-is-quantum", "anchor": "کوانتوم یعنی چه"}, {"from": "decoherence", "anchor": "واهمدوسی"}, {"from": "energy-levels", "anchor": "ترازهای انرژی"}], "content_html": "<p><strong>نکات کلیدی:</strong> تله پورت کوانتومی جابه‌جایی ماده نیست، انتقال حالت کوانتومی یک ذره به ذره‌ای دیگر دور است بدون رفتن خود ذره. بنت ۱۹۹۳ نظریه و ۱۹۹۷ آزمایش فوتون و ۲۰۱۷ میسیوس ۵۰۰km. قضیه عدم کپی (ووترز-زورک ۱۹۸۲) می‌گوید حالت ناشناخته کپی نمی‌شود؛ برای خواندن دقیق باید اصل نابود شود. مثل قالی ابریشم کاشان که برای اسکن دقیق باید تار و پودش باز شود. انسان ۱۰^۲۸ اتم با حالت‌های درهم‌تنیده و واهمدوسی ۱۰^-20 ثانیه دارد. اگر تله پورت انسان را بفهمید، فرق اطلاعات و ماده را فهمیده‌اید.</p><p>خبر «دانشمندان تله پورت کردند» واقعی است اما معنایش چیز دیگر است.</p><h2>تله پورت کوانتومی واقعاً یعنی چه؟</h2><p>انتقال حالت نه ماده. نسخه خطی حافظ: محتوا روی کاغذ سفید شهر دیگر بازنویسی می‌شود اما اصل باید همان لحظه سوزانده شود — هرگز دو نسخه همزمان نیست. <a href=\"https://qpedia.ir/quantum-teleportation/\">تله پورت کوانتومی</a> و <a href=\"https://qpedia.ir/quantum-internet-satellite/\">اینترنت کوانتومی</a> و <a href=\"https://qpedia.ir/photon/\">فوتون</a> را ببینید.</p><h2>قضیه عدم کپی؛ مانع اصلی</h2><p>حالت ناشناخته کپی نمی‌شود — نتیجه خطی بودن کوانتوم و بدون راه فرار. برای انسان باید هر اتم و الکترون و پیوند و حالت مغز خوانده شود و در این خواندن نابود شود. اطلاعات حاصل نجومی: ۱۰^۴۵ بیت برای موقعیت و حالت‌ها، ذخیره ناممکن. حتی اگر، بازسازی نیاز به اسمبل اتم به اتم با دقت کوانتومی و غلبه بر <a href=\"https://qpedia.ir/decoherence/\">واهمدوسی</a> دارد که در بدن ۱۰^-20 ثانیه است. <a href=\"https://qpedia.ir/what-is-quantum/\">کوانتوم</a> و <a href=\"https://qpedia.ir/energy-levels/\">ترازها</a> را ببینید.</p><h2>بررسی عمیق‌تر تله پورت انسان</h2><p>سه مانع: ۱) اطلاعاتی: ۱۰^۲۸ اتم × ۳ مختصات × دقت کوانتومی ~۱۰^۳۲ بیت، بیشتر از کل ذخیره جهان. ۲) فیزیکی: عدم کپی و واهمدوسی، هر اندازه‌گیری حالت را خراب می‌کند. ۳) فلسفی: آیا کپی بازسازی‌شده شما هستید یا فقط کپی؟ پارادوکس تسیوس. اعداد: تله پورت فوتون ۱۴۴km رکورد، تله پورت انسان نیاز به انرژی 10^19 ژول (کل مصرف سالانه جهان). کاربرد واقعی تله پورت: شبکه کوانتومی نه جابه‌جایی انسان.</p>\n<h2>چرا این موضوع فراتر از آزمایشگاه مهم است؟</h2>\n<p>کوانتوم انتزاعی به نظر می‌رسد اما همین امروز در جیب و بیمارستان و نیروگاه است. هر گوشی هزاران ترانزیستور با شکاف نواری کوانتومی دارد. هر MRI اسپین هسته‌ای می‌خواند. هر لیزر از ترازهای انرژی می‌آید. هر پنل خورشیدی فوتوالکتریک است. پس فهم کوانتوم فهم فناوری اطراف است. از طرف دیگر، همین جذابیت باعث سوءاستفاده بازاری می‌شود: هر جا کلمه کوانتوم را دیدید که بدون عدد و آزمایش نتیجه پول و درمان می‌دهد، شک کنید. علم واقعی عدد، خطا، و بازتولید دارد.</p>\n<p>سه معیار ساده برای هر ادعای کوانتومی: 1) آیا فرمول یا عدد دارد؟ 2) آیا آزمایش مستقل تکرار کرده؟ 3) آیا مجله معتبر با داوری منتشر کرده؟ اگر نه، احتمالاً شبه‌علم است. این چک‌لیست از <a href=\"https://qpedia.ir/spot-pseudoscience-one-sentence/\">تشخیص شبه‌علم</a> می‌آید.</p>\n<h2>یک داستان واقعی از آزمایشگاه</h2>\n<p>در آزمایشگاه‌های واقعی، کوانتوم با خلأ بسیار بالا، دمای میلی‌کلوین، لیزر پایدار، و ساعت‌ها تنظیم می‌آید. یک روز آزمایش موفق، هفته‌ها شکست دارد. همین سختی دلیل پیشرفت است: هر کیوبیت اضافه ماه‌ها کار می‌برد. داستان LK-99 و Majorana 1 نشان داد هیجان رسانه‌ای بدون داده باز، علم را کند می‌کند. بهترین دانشمندان اولین کسانی هستند که می‌گویند «شاید اشتباه می‌کنم، آزمایش کنید».</p>\n<h2>جزئیات بیشتر برای علاقه‌مندان جدی</h2>\n<p>اگر می‌خواهید عمیق‌تر بروید، سه سطح وجود دارد: شهودی، ریاضی، آزمایشگاهی. شهودی با تمثیل استوانه و نردبان و گیتار شروع می‌شود. ریاضی با معادله شرودینگر و اصل عدم قطعیت و اسپین 1/2 ادامه می‌یابد. آزمایشگاهی با خلأ 10^-10 میلی‌بار و دمای 10 میلی‌کلوین و لیزر قفل‌شده به حفره. هر سطح دقت بیشتری می‌دهد اما هزینه بیشتری هم دارد. برای شروع، شهودی کافی است اما برای پژوهش، هر سه لازم است.</p>\n<p>سه آزمایش تاریخی که هر فیزیکدان باید بداند: یانگ 1801 تداخل، اشترن-گرلاخ 1922 کوانتش اسپین، بل-آسپه 1982 نقض رئالیسم موضعی. هر سه با وسایل ساده شروع شدند اما جهان‌بینی را عوض کردند. امروز همان آزمایش‌ها با مولکول 2000 اتمی و فاصله 144 کیلومتر تکرار می‌شوند و هنوز کوانتوم پیروز است.</p>\n<p>اعداد کلیدی: ثابت پلانک 6.626e-34، سرعت نور 299792458، بار الکترون 1.602e-19، جرم الکترون 9.11e-31، بسامد سزیم 9192631770. این اعداد جهان را می‌سازند.</p>\n<h2>ارتباط با فناوری امروز و فردا</h2>\n<p>کوانتوم فقط گذشته نیست، آینده هم هست: کامپیوتر کوانتومی با کیوبیت‌های ابررسانا و یون و فوتون، حسگر کوانتومی با دقت 10^-18 برای گرانش‌سنجی، رمز کوانتومی با امنیت از دل بل، و مواد کوانتومی با توپولوژی. هر کدام چالش خطا دارند و راه‌حل‌های مختلف: تصحیح خطا، حفاظت توپولوژیک، واهمدوسی کنترل‌شده. ده سال آینده، بعضی از این‌ها از آزمایشگاه به خانه می‌آیند مثل ترانزیستور که از آزمایشگاه بل 1947 به جیب شما آمد.</p>\n\n<h2>سه آزمایش که باید بشناسید</h2>\n<p>آزمایش اول با نور و تداخل، آزمایش دوم با اسپین و میدان مغناطیسی، آزمایش سوم با درهم‌تنیدگی و فاصله زیاد. هر سه با دقت بالا کوانتوم را تأیید کرده‌اند و هیچ کدام با فیزیک کلاسیک قابل توضیح کامل نیستند. دانستن جزئیات این آزمایش‌ها مرز علم و شبه‌علم را روشن می‌کند.</p>\n<p>آزمایش اول: تداخل تک‌فوتون یا تک‌الکترون با دو شکاف که نوار می‌سازد. آزمایش دوم: اشترن-گرلاخ با دو لکه مجزا نه پیوسته. آزمایش سوم: بل با همبستگی فراتر از حد کلاسیک. این سه ستون فهم کوانتوم هستند.</p>\n\n<h2>سوءبرداشت‌های رایج</h2><p><strong>سوءبرداشت 1: تله پورت یعنی جابه‌جایی ماده.</strong> نه؛ انتقال حالت.</p><p><strong>سوءبرداشت 2: چون فوتون تله پورت شد پس انسان هم می‌شود.</strong> نه؛ مقیاس و واهمدوسی فرق نجومی دارد.</p><p><strong>سوءبرداشت 3: عدم کپی دور زده می‌شود.</strong> نه؛ قضیه بنیادی است.</p><p><strong>سوءبرداشت 4: تله پورت همان کپی است.</strong> نه؛ اصل نابود می‌شود.</p><h2>جمع‌بندی</h2><p>۱) تله پورت حالت است نه ماده. ۲) عدم کپی مانع کپی‌برداری بدون نابودی. ۳) انسان از نظر اطلاعاتی و فیزیکی و فلسفی غیرقابل تله پورت.</p><h2>پرسش‌های متداول</h2><p><strong>آیا تله پورت واقعی است؟</strong><br>برای حالت کوانتومی فوتون بله، برای ماده نه.</p><p><strong>چرا انسان نه؟</strong><br>اطلاعات نجومی و واهمدوسی و عدم کپی.</p><p><strong>آیا کپی من همان من است؟</strong><br>فلسفی؛ فیزیکی کپی است نه تداوم آگاهی.</p><p><strong>ماهواره میسیوس چه کرد؟</strong><br>حالت فوتون را ۵۰۰km تله پورت کرد.</p><p><strong>آینده تله پورت چیست؟</strong><br>شبکه کوانتومی و کامپیوتر توزیع‌شده.</p><h2>منابع</h2><ol class=\"qpedia-scientific-sources\"><li><a href=\"https://doi.org/10.1103/PhysRevLett.70.1895\" target=\"_blank\">Bennett et al., Teleportation, 1993.</a></li><li><a href=\"https://doi.org/10.1038/29972\" target=\"_blank\">Bouwmeester et al., Experimental teleportation, Nature 1997.</a></li><li><a href=\"https://doi.org/10.1038/nature13512\" target=\"_blank\">No-cloning theorem, Nature 1982.</a></li><li><a href=\"https://plato.stanford.edu/entries/qt-teleportation/\" target=\"_blank\">Stanford Encyclopedia, Teleportation.</a></li></ol>", "old_score": 58}, {"slug": "law-of-attraction-quantum", "title": "قانون جذب و کوانتوم؛ کجای این استدلال می لنگد؟", "seo_title": "قانون جذب و کوانتوم؛ کجای استدلال می‌لنگد؟ توضیح دقیق", "meta_description": "قانون جذب و کوانتوم می‌گوید ذهن واقعیت می‌سازد و به کوانتوم استناد می‌کند. اما ناظر در کوانتوم آشکارساز است نه آگاهی و واهمدوسی بدون انسان هم اثر می‌کند.", "focus_keyword": "قانون جذب و کوانتوم", "featured_image": "law-of-attraction-quantum-fallacy.webp", "featured_alt": "قانون جذب و کوانتوم و مغالطه ناظر و واهمدوسی", "inbound_suggestions": [{"from": "double-slit-experiment", "anchor": "آزمایش دو شکاف"}, {"from": "decoherence", "anchor": "واهمدوسی"}, {"from": "what-is-quantum", "anchor": "کوانتوم یعنی چه"}, {"from": "spot-pseudoscience-one-sentence", "anchor": "تشخیص شبه‌علم"}, {"from": "everything-is-energy-claim", "anchor": "همه چیز انرژی است"}, {"from": "is-the-brain-quantum", "anchor": "آیا مغز کوانتومی است"}], "content_html": "<p><strong>نکات کلیدی:</strong> قانون جذب کوانتومی در چهار گام خلاصه می‌شود: ۱) ذرات قبل اندازه‌گیری وضعیت مشخص ندارند ۲) ناظر وضعیت را مشخص می‌کند ۳) پس ذهن واقعیت می‌سازد ۴) پس با فکر واقعیت عوض می‌شود. گام ۱ و ۲ با تسامح درست، ۳ جهش بی‌پشتوانه، ۴ بی‌ارتباط. ناظر در کوانتوم یعنی هر برهم‌کنش فیزیکی که اطلاعات مبادله کند: آشکارساز، فوتون سرگردان، مولکول هوا — نه آگاهی انسان. اگر قانون جذب و کوانتوم را بفهمید، مغالطه ابهام را فهمیده‌اید.</p><p>جمله‌ها آشنا: «کوانتوم ثابت کرده ذهن واقعیت می‌سازد»، «با فرکانس افکارت جذب می‌کنی». این ادعاها با دقت طراحی شده‌اند تا باورپذیر باشند.</p><h2>مغالطه اول؛ ناظر یعنی چه؟</h2><p>انتخاب واژه بد تاریخی. مشاهده یعنی برهم‌کنش فیزیکی نه نگاه انسان. در دو شکاف الگو وقتی می‌رود که دستگاه مسیر را ثبت کند حتی اگر هیچ انسانی نباشد و داده هرگز خوانده نشود. آزمایش‌ها شبانه خودکار اجرا می‌شوند و نتیجه یکی است. سازوکار واهمدوسی است: تماس با محیط ویژگی کوانتومی را می‌برد. هیچ آگاهی لازم نیست. <a href=\"https://qpedia.ir/double-slit-experiment/\">دو شکاف</a> و <a href=\"https://qpedia.ir/decoherence/\">واهمدوسی</a> و <a href=\"https://qpedia.ir/what-is-quantum/\">کوانتوم</a> را ببینید.</p><h2>مغالطه دوم؛ از ذره به انسان</h2><p>حتی اگر ذهن روی یک الکترون اثر می‌گذاشت (که نمی‌گذارد)، پرش به «پس با فکر ثروت جذب می‌کنی» جهش مقیاس نجومی است. مغز ۲۰ وات، میدانش در ۱ متر از نویز کمتر، آهنربای یخچال میلیون‌ها برابر قوی‌تر و فقط آهن جذب می‌کند. <a href=\"https://qpedia.ir/everything-is-energy-claim/\">همه چیز انرژی است</a> و <a href=\"https://qpedia.ir/is-the-brain-quantum/\">آیا مغز کوانتومی است</a> و <a href=\"https://qpedia.ir/spot-pseudoscience-one-sentence/\">تشخیص شبه‌علم</a> را ببینید.</p><h2>بررسی عمیق‌تر قانون جذب</h2><p>آزمون ابطال‌پذیری پوپر: چه آزمایشی قانون جذب را رد می‌کند؟ اگر هیچ آزمایشی نتواند رد کند، علم نیست. کارآزمایی‌های قانون جذب هیچ کدام دوسوکور و تکرارپذیر با اثر فراتر از دارونما و سوگیری تأیید نیستند. سه نشانه شبه‌علم: بدون عدد، بدون روش تکرارپذیر، بدون مقاله همتا-داوری، با ادعای بزرگ و استناد به اینشتین بدون منبع. اعداد: اثر دارونما ۲۰-۳۰%، اثر قانون جذب در مطالعات معتبر صفر. کاربرد واقعی کوانتوم: ترانزیستور و MRI نه جذب.</p>\n<h2>چرا این موضوع فراتر از آزمایشگاه مهم است؟</h2>\n<p>کوانتوم انتزاعی به نظر می‌رسد اما همین امروز در جیب و بیمارستان و نیروگاه است. هر گوشی هزاران ترانزیستور با شکاف نواری کوانتومی دارد. هر MRI اسپین هسته‌ای می‌خواند. هر لیزر از ترازهای انرژی می‌آید. هر پنل خورشیدی فوتوالکتریک است. پس فهم کوانتوم فهم فناوری اطراف است. از طرف دیگر، همین جذابیت باعث سوءاستفاده بازاری می‌شود: هر جا کلمه کوانتوم را دیدید که بدون عدد و آزمایش نتیجه پول و درمان می‌دهد، شک کنید. علم واقعی عدد، خطا، و بازتولید دارد.</p>\n<p>سه معیار ساده برای هر ادعای کوانتومی: 1) آیا فرمول یا عدد دارد؟ 2) آیا آزمایش مستقل تکرار کرده؟ 3) آیا مجله معتبر با داوری منتشر کرده؟ اگر نه، احتمالاً شبه‌علم است. این چک‌لیست از <a href=\"https://qpedia.ir/spot-pseudoscience-one-sentence/\">تشخیص شبه‌علم</a> می‌آید.</p>\n<h2>یک داستان واقعی از آزمایشگاه</h2>\n<p>در آزمایشگاه‌های واقعی، کوانتوم با خلأ بسیار بالا، دمای میلی‌کلوین، لیزر پایدار، و ساعت‌ها تنظیم می‌آید. یک روز آزمایش موفق، هفته‌ها شکست دارد. همین سختی دلیل پیشرفت است: هر کیوبیت اضافه ماه‌ها کار می‌برد. داستان LK-99 و Majorana 1 نشان داد هیجان رسانه‌ای بدون داده باز، علم را کند می‌کند. بهترین دانشمندان اولین کسانی هستند که می‌گویند «شاید اشتباه می‌کنم، آزمایش کنید».</p>\n<h2>جزئیات بیشتر برای علاقه‌مندان جدی</h2>\n<p>اگر می‌خواهید عمیق‌تر بروید، سه سطح وجود دارد: شهودی، ریاضی، آزمایشگاهی. شهودی با تمثیل استوانه و نردبان و گیتار شروع می‌شود. ریاضی با معادله شرودینگر و اصل عدم قطعیت و اسپین 1/2 ادامه می‌یابد. آزمایشگاهی با خلأ 10^-10 میلی‌بار و دمای 10 میلی‌کلوین و لیزر قفل‌شده به حفره. هر سطح دقت بیشتری می‌دهد اما هزینه بیشتری هم دارد. برای شروع، شهودی کافی است اما برای پژوهش، هر سه لازم است.</p>\n<p>سه آزمایش تاریخی که هر فیزیکدان باید بداند: یانگ 1801 تداخل، اشترن-گرلاخ 1922 کوانتش اسپین، بل-آسپه 1982 نقض رئالیسم موضعی. هر سه با وسایل ساده شروع شدند اما جهان‌بینی را عوض کردند. امروز همان آزمایش‌ها با مولکول 2000 اتمی و فاصله 144 کیلومتر تکرار می‌شوند و هنوز کوانتوم پیروز است.</p>\n<p>اعداد کلیدی: ثابت پلانک 6.626e-34، سرعت نور 299792458، بار الکترون 1.602e-19، جرم الکترون 9.11e-31، بسامد سزیم 9192631770. این اعداد جهان را می‌سازند.</p>\n<h2>ارتباط با فناوری امروز و فردا</h2>\n<p>کوانتوم فقط گذشته نیست، آینده هم هست: کامپیوتر کوانتومی با کیوبیت‌های ابررسانا و یون و فوتون، حسگر کوانتومی با دقت 10^-18 برای گرانش‌سنجی، رمز کوانتومی با امنیت از دل بل، و مواد کوانتومی با توپولوژی. هر کدام چالش خطا دارند و راه‌حل‌های مختلف: تصحیح خطا، حفاظت توپولوژیک، واهمدوسی کنترل‌شده. ده سال آینده، بعضی از این‌ها از آزمایشگاه به خانه می‌آیند مثل ترانزیستور که از آزمایشگاه بل 1947 به جیب شما آمد.</p>\n\n<h2>سه آزمایش که باید بشناسید</h2>\n<p>آزمایش اول با نور و تداخل، آزمایش دوم با اسپین و میدان مغناطیسی، آزمایش سوم با درهم‌تنیدگی و فاصله زیاد. هر سه با دقت بالا کوانتوم را تأیید کرده‌اند و هیچ کدام با فیزیک کلاسیک قابل توضیح کامل نیستند. دانستن جزئیات این آزمایش‌ها مرز علم و شبه‌علم را روشن می‌کند.</p>\n<p>آزمایش اول: تداخل تک‌فوتون یا تک‌الکترون با دو شکاف که نوار می‌سازد. آزمایش دوم: اشترن-گرلاخ با دو لکه مجزا نه پیوسته. آزمایش سوم: بل با همبستگی فراتر از حد کلاسیک. این سه ستون فهم کوانتوم هستند.</p>\n\n<h2>سوءبرداشت‌های رایج</h2><p><strong>سوءبرداشت 1: ناظر یعنی آگاهی.</strong> نه؛ آشکارساز فیزیکی.</p><p><strong>سوءبرداشت 2: عدم قطعیت یعنی هر چیزی ممکن است.</strong> نه؛ فقط احتمال‌های مجاز شرودینگر.</p><p><strong>سوءبرداشت 3: چون کوانتوم عجیب است پس هر ادعای عجیبی درست است.</strong> نه؛ عجیب بودن دلیل بی‌قانونی نیست.</p><p><strong>سوءبرداشت 4: قانون جذب بی‌ضرر است.</strong> نه؛ پول و زمان و سلامت می‌برد و مقصر دانستن قربانی.</p><h2>جمع‌بندی</h2><p>۱) ناظر آشکارساز است نه آگاهی. ۲) پرش از ذره به ثروت جهش مقیاس و مغالطه است. ۳) آزمون ابطال‌پذیری و کارآزمایی معتبر ندارد.</p><h2>پرسش‌های متداول</h2><p><strong>آیا ذهن روی ماده اثر می‌گذارد؟</strong><br>در حد ۲۰ وات مغز و میدان ناچیز، نه در حد جذب ثروت.</p><p><strong>آیا دو شکاف ثابت می‌کند آگاهی مهم است؟</strong><br>نه؛ دستگاه بدون انسان هم تداخل را می‌برد.</p><p><strong>آیا قانون جذب علمی است؟</strong><br>نه؛ هیچ کارآزمایی معتبر ندارد.</p><p><strong>چرا باورپذیر است؟</strong><br>چون از کلمات علمی با معنای عامیانه استفاده می‌کند.</p><p><strong>چطور شبه‌علم را تشخیص دهم؟</strong><br>چک‌لیست ۴ نشانه و آزمون ابطال‌پذیری.</p><h2>منابع</h2><ol class=\"qpedia-scientific-sources\"><li><a href=\"https://plato.stanford.edu/entries/pseudoscience/\" target=\"_blank\">Stanford Encyclopedia, Pseudoscience.</a></li><li><a href=\"https://doi.org/10.1103/RevModPhys.75.715\" target=\"_blank\">Zurek, Decoherence, 2003.</a></li><li><a href=\"https://plato.stanford.edu/entries/qm-measurement/\" target=\"_blank\">Stanford Encyclopedia, Measurement.</a></li><li><a href=\"https://doi.org/10.1086/392638\" target=\"_blank\">Sagan, Baloney detection, 1996.</a></li></ol>", "old_score": 58}]', true);
}
